window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch11"]={"id": "ch11", "title": "第六章(二) 细胞信号转导", "sub": "翟中和《细胞生物学》第4版 · 教师课件逐页详解", "sub2": "信号通路 · 网络 · 受体", "modules": [{"i": 0, "name": "4.1.2 G-蛋白偶联受体", "slides": [{"i": 0, "sec": "4.1.2 G-蛋白偶联受体", "title": "4.1.2 G-蛋白偶联受体", "notes": "效应器（二）腺苷酸环化酶→cAMP-PKA 信号通路\n细胞外信号与相应的G蛋白偶联\n受体结合，导致细胞内第二信使\ncAMP的水平变化而引起细胞反\n应的信号通路。\n大多数哺乳动物细胞应答激素反应的\n主要机制之一。\n磷酸二酯酶\n【结合课本/笔记】cAMP信号通路反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶GPLR的失敏（desensitization）与减量调节细菌毒素对G蛋白的修饰作用", "page": 1, "level": "掌握", "img": "assets/img/ch11/p001.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 1, "sec": "4.1.2 G-蛋白偶联受体", "title": "cAMP -PKA 信号通路", "notes": "信号分子与G蛋白偶联受体结合\n受体构象改变，G蛋白活化-GTP\n活化腺苷酸环化酶，产生cAMP\n活化蛋白激酶A(PKA)\n一些特定的蛋白磷酸化     如：动物肝脏、肌肉应答肾上腺\n素、胰高血糖素，分解糖原，生成\n引起一系列生物学反应     葡萄糖。-肝脏和肌肉是人体调节糖\n原代谢、血糖浓度的主要组织。\n【结合课本/笔记】cAMP信号通路反应链：激素→G-蛋白偶联受体→G-蛋白→腺苷酸环化酶→cAMP→cAMP依赖的蛋白激酶A→基因调控蛋白→基因转录组分及其分析G-蛋白偶联受体G-蛋白活化与调节效应酶——腺苷酸环化酶GPLR的失敏（desensitization）与减量调节细菌毒素对G蛋白的修饰作用", "page": 2, "level": "掌握", "img": "assets/img/ch11/p002.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 2, "sec": "4.1.2 G-蛋白偶联受体", "title": "在多细胞动物各种以cAMP为第二信使的信号通路", "notes": "中，主要是通过激活蛋白激酶A kinase A来起作用。\ncAMP特\n异结合到\n蛋白激酶\nKinase A     A的调节\n亚基上\n释放 蛋白\n激酶 A的\n催化亚基", "page": 3, "level": "掌握", "img": "assets/img/ch11/p003.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 3, "sec": "4.1.2 G-蛋白偶联受体", "title": "1 胞质功能：", "notes": "Kinase A\n肝脏/肌细胞糖原分解（短\n期快速应答）\n动物体内，葡萄糖是以不溶的\n糖原形式储存的。糖原分解受\n胰高血糖素和肾上腺素控制。\n2 细胞核功能：\n调节基因表达", "page": 4, "level": "掌握", "img": "assets/img/ch11/p004.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 4, "sec": "4.1.2 G-蛋白偶联受体", "title": " 肾上腺细胞：肾上腺素", "notes": "肝脏细胞表面G-蛋白偶联受体\n G－蛋白-GTP\n激活腺苷酸环化酶(adenylyl cylase)\nATP→cAMP\n蛋白激酶A（PKA）\n肝细胞细胞质中\n➢ 磷酸化&激活糖原磷酸化酶激酶(glycogen phosphorylase\nkinase, GPK)，催化GP磷酸化后激活，促进糖原分解；\n➢ 磷酸化&抑制糖原合成酶(GS)，抑制糖原合成。\n血糖浓度升高", "page": 5, "level": "掌握", "img": "assets/img/ch11/p005.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 5, "sec": "4.1.2 G-蛋白偶联受体", "title": "肾上腺素刺激骨骼肌细", "notes": "胞中的糖原分解\nGPK        糖原磷酸化酶激酶被激活\nGP   糖原磷酸化酶\n糖原分解", "page": 6, "level": "掌握", "img": "assets/img/ch11/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "4.1.2 G-蛋白偶联受体", "title": "糖原磷酸化酶激酶", "notes": "糖原合成酶\n糖原磷酸化酶", "page": 7, "level": "掌握", "img": "assets/img/ch11/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "4.1.2 G-蛋白偶联受体", "title": " 细胞核功能：调节基因表达", "notes": "Kinase A\n激活的胞质溶胶中的蛋白激酶A，2个\n催化亚基随后可转移入细胞核，\nkinase A磷酸化转录因子CREB\n(cAMP response element-binding\nprotein)作用于DNA的特定核苷酸序\n列位点(CRE，cAMP response\nelement)，\n增强相应基因的转录起始速率。如与\n糖异生有关的酶，其编码基因均含有\nCRE序列。\n利用小分子前体合成葡萄糖", "page": 8, "level": "掌握", "img": "assets/img/ch11/p008.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 8, "sec": "4.1.2 G-蛋白偶联受体", "title": "激素和神经递质与", "notes": "G蛋白偶联受体结合\n腺苷酸环化酶，\ncAMP\n激活胞质中的PKA\nPKA随后转移入细胞核，\n磷酸化一个转录因子\n(CREB)\n激活一整套靶基因的转录。", "page": 9, "level": "掌握", "img": "assets/img/ch11/p009.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch11_mcq_3", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "在 cAMP 信号中，G 蛋白的偶联作用表现为（            ）。", "o": ["A．受体的活化导致 G 蛋白的α、β、γ三个亚单位的偶联", "B．受体的活化通过 G 蛋白与 MAPK 激酶级联反应通路偶联", "C．受体的活化通过 G 蛋白与 PKA(cAMP-dependent protein kinase A)的活化偶联 n 受体的活 化通过 G 蛋白与 AC(adenyl cyclase)的活化偶联", "D．受体的活化通过 G 蛋白与 cAMP 偶联 【答案】D  【解析】在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。"], "a": "D", "e": "在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。", "kp": "ch11_s0_0"}, {"id": "ch11_mcq_5", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "一氧化氮受体是（            ）。", "o": ["A．G 蛋白偶联受体", "B．鸟苷酸环化酶", "C．腺苷酸环化酶", "D．受体酪氨酸激酶 【答案】B  【解析】NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。"], "a": "B", "e": "NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。", "kp": "ch11_s0_0"}, {"id": "ch11_mcq_6", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "有关 cAMP 信号通路，下列说法错误的是（              ）。", "o": ["A．被激活的蛋白激酶 A 的催化亚基转位进入细胞核，使基因调控蛋白磷酸化", "B．结合 GTP 的α亚基具有活性，而βγ亚基复合物没有活性", "C．βγ亚基复合物与游离的 Gs 的α亚基结合，可使 Gs 的α亚基失活", "D．这一通路的首要效应酶是腺苷酸环化酶，cAMP 被环腺苷磷酸二酯酶消除 【答案】B  【解析】当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。"], "a": "B", "e": "当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。", "kp": "ch11_s0_2"}], "judge": [{"id": "ch11_judge_2", "modI": 0, "q": "G 蛋白偶联受体中，霍乱毒素使 G 蛋白α亚基不能活化，百日咳毒素使 G 蛋白α亚基持续 活化。（      ）", "a": "错", "e": "霍乱毒素，使α亚基丧失 GTP 酶的活性并处于持续活化状态；百日咳毒素抑制 Gi 的活性。", "kp": "ch11_s0_8"}], "fill": [{"id": "ch11_fill_2", "modI": 0, "q": "cAMP 信号通路的效应酶是______，磷脂酰肌醇信号通路的效应酶是______。", "a": "腺苷酸环化酶；磷脂酶 C", "kp": "ch11_s0_0"}, {"id": "ch11_fill_4", "modI": 0, "q": "受体的本质是______，构成______。", "a": "激素激活的基因调控蛋白；细胞内受体超家族", "kp": "ch11_s0_0"}, {"id": "ch11_fill_5", "modI": 0, "q": "G 蛋白耦联受体是细胞表面由______条多肽______次跨膜形成的受体，N 端在______，C 端在______。N 端与______结合，C 端与______作用。", "a": "单；7；外；内；信号；G 蛋白", "kp": "ch11_s0_4"}, {"id": "ch11_fill_6", "modI": 0, "q": "第一信使指______。", "a": "细胞外信号分子", "kp": "ch11_s0_0"}, {"id": "ch11_fill_7", "modI": 0, "q": "硝酸甘油能用于治疗心绞痛是因为______。", "a": "硝酸甘油在体内转化为 NO，可舒张血管", "kp": "ch11_s0_0"}, {"id": "ch11_fill_9", "modI": 0, "q": "无活性的蛋白激酶 A 有______和______亚基，cAMP 结合它的______使其激活。", "a": "调节亚基；无活性的催化；调节亚基", "kp": "ch11_s0_2"}], "short": [{"id": "ch11_short_3", "modI": 0, "q": "G 蛋白偶联受体与酶联受体有什么主要不同点？", "a": "蛋白偶联受体都含有 7 次跨膜的结构域，在信号转导中全部与 G 蛋白偶联；酶联受体 都属于单次跨膜受体，当该类受体与配体结合时导致受体二聚化形成同源或异源多聚化。", "kp": "ch11_s0_8"}, {"id": "ch11_short_4", "modI": 0, "q": "简述 cAMP 途径中的 Gs 调节模型。", "a": "在该途径中由刺激型 Gs 蛋白复合物偶联刺激型受体与腺苷酸环化酶。当细胞没有接受 刺激信号时，Gs 处于非活化状态，Gs 蛋白为异三聚体，α亚基与 GDP 结合，这时腺苷酸环 化酶没有活性。当刺激型的第一信使作用于刺激型的受体后，导致受体构象改变，受体复合 物与 GS 结合引起 Gs 的α亚基构象变化排斥 GDP，而与 GTP 结合被活化，三聚体 Gs 解离 出α亚基和贝塔嘎嘛亚基复合物，活化的刺激型 Gsα亚基继激活腺苷酸环化酶的活性，从而 产生第二信使 cAMP，由于 cAMP 的浓度升高，引起细胞内依赖于 cAMP 的靶酶活化，由 此将胞外信号转换成胞内信号传递、放大以致调节细胞生理反应或基因的表达等。随着 GTP 的水解使α亚基恢复原来的构象并导致与腺苷酸环化酶解离，终止腺苷酸环化酶的活化作 用,α亚基和βγ亚基重新结合，使细胞回复到静止状态。", "kp": "ch11_s0_8"}], "calc": [{"id": "ch11_calc_3", "modI": 0, "q": "如何理解信号系统及其功能?", "a": "（1）信号系统的基本组成及信号蛋白 ①通过细胞表面受体介导的信号途径的步骤组成： a．细胞通过特异性受体识别胞外信号分子； b．信号跨膜转导； c．通过胞内级联反应实现信号放大作用，并终止细胞活性改变； d．由于信号分子失活，细胞反应终止或下调。 ②相关信号蛋白： a．细胞表面受体；b．转承蛋白；c．信使蛋白；d．接头蛋白；e．放大和转导蛋白；f．传 感蛋白；g．分歧蛋白；h．整合蛋白；i．潜在基因调控蛋白。 （2）信号转导系统的功能 ①相关信号蛋白的功能如下： a．细胞表面受体：特异识别胞外信号。 b．转承蛋白：负责信息向下传递。 c．信使蛋白：携带信号从一部分传递到另外一部分。 d．接头蛋白：连接信号蛋白。 e．放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。 f．传感蛋白：负责不同形式信号的转换。 g．分歧蛋白：信号从一条途径传递到另外一条途径。 h．整合蛋白：从多条通路接受信号并向下传递。 i．潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。 ②细胞内信号蛋白的相互作用是靠蛋白质模式结合域特异性介导的。信号蛋白具有不同的模 式结合域与另一相匹配的基序识别并结合，在细胞内组装成不同的信号转导复合物，构成细 胞内信号传递通路的基础。 ③信号转导系统的主要作用：特异性、放大作用、信号终止、整合作用。", "kp": "ch11_s0_0"}], "term": [{"id": "ch11_term_6", "modI": 0, "term": "蛋白激酶 VS 蛋白酶体", "def": "蛋白激酶又称蛋白质磷酸化酶，是一类催化蛋白质磷酸化反应的酶，能够特异性地在某 些蛋白质的某些氨基酸位点上添加磷酸基团。蛋白激酶在细胞内的分布遍及核、线粒体、微 粒体和胞液。一般分为 3 大类：①底物专一的蛋白激酶：如磷酸化酶激酶，丙酮酸脱氢酶激 酶等。②依赖于环核苷酸的蛋白激酶：如环腺苷酸（cAMP）蛋白激酶，环鸟苷酸（cGMP） 蛋白激酶。③其他蛋白激酶：如组蛋白激酶等。 蛋白酶体是一类能降解细胞不需要的或受到损伤蛋白质的蛋白复合物。经过蛋白酶体的作用， 蛋白质被切断为约 7～8 个氨基酸长的肽段，这些肽段可以被进一步降解为单个氨基酸分子， 然后被用于合成新的蛋白质。蛋白酶体是细胞用来调控特定蛋白质和除去错误折叠蛋白质的 主要机制。一般来说，需要被降解的蛋白质会先被一个称为泛素的小型蛋白质所标记，被标 记上的蛋白质就会被蛋白酶体降解，因此人们常把蛋白酶体和泛素结合起来，将这一过程称 为泛素依赖性蛋白酶体降解途径。", "kps": "", "kp": "ch11_s0_6"}]}, {"i": 1, "name": "4.1.3 G蛋白偶联受体", "slides": [{"i": 9, "sec": "4.1.3 G蛋白偶联受体", "title": "4.1.3 G蛋白偶联受体", "notes": "效应器(三)磷脂酶C(PLC)\n－肌醇磷脂信号通路(又称双信使系统)\n 胞外信号分子与细胞表面G蛋白偶联受体结合，激活质膜上\n的磷脂酶C(PLC)\n质膜上的4，5-二磷酸磷脂酰肌醇（PIP2）水解成1,4,5-三磷\n酸肌醇（IP3）和二酰基甘油(DAG)两个第二信使，胞外信号转\n变为胞内信号。\nIP3水溶性小分子，离开质膜迅速在胞质溶胶中扩散。使内质\n网Ca2+ 通道打开，释放Ca2+到胞质，细胞内 Ca2+溶度升高；\nCa2+ 协同DAG激活蛋白激酶C(PKC)，PKC 进一步磷酸化底物\n蛋白。", "page": 10, "level": "掌握", "img": "assets/img/ch11/p010.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 10, "sec": "4.1.3 G蛋白偶联受体", "title": "（本页为图片/无文字层）", "notes": "【图内文字(OCR)】\nfatty acid chains of inner\nlipid monolayer of\nplasma membrane\nO=\nC=O\n=O\nC=O\n.\nCYTOSOL\nCH2-CH-CH2\nCH2-CH-CH2\nOH\nACTIVATES\nO=P-O-\n-O-P=O\ndiacylglycerol\nPROTEINKINASEC\nphospholipase C-β\n®\nOH\nOH HO\n1\nO=P-O-\n-O-P=O\nO=P-O-\nO\nRELEASES Ca2+\nOH\nFROMTHE\nOHHO\nENDOPLASMIC\nP14,5-bisphosphate[PI(4,5)P2]\nRETICULUM\nO=P-O-\ninositol 1,4,5-trisphosphate (IP3)\n【中文讲解·对照课本/考点】\n考点：4.1.3 G蛋白偶联受体\n• 磷脂酰肌醇信号通路 “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→", "page": 11, "level": "掌握", "img": "assets/img/ch11/p011.jpg", "anim": null, "fig": null, "points": ["fatty acid chains of inner", "lipid monolayer of", "plasma membrane", "O=", "C=O", "=O", "C=O", "CYTOSOL"], "check": null, "cards": null}, {"i": 11, "sec": "4.1.3 G蛋白偶联受体", "title": "肌醇磷脂信号通路", "notes": "信号分子与G蛋白偶联受体结合\n活化的受体通过G蛋白激活磷酸脂酶C\nPIP2\nIP3          +       DAG\n从ER 钙库中释放Ca2+       活化蛋白激酶C(PKC)\n调节一系列生物学反应\n又称PKC系统(protein kinase C system)", "page": 12, "level": "掌握", "img": "assets/img/ch11/p012.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 12, "sec": "4.1.3 G蛋白偶联受体", "title": "－蛋白激酶C为细胞质酶，在未受刺激的细胞", "notes": "中水溶性，游离在细胞质中，非活性状态；\nDAG和Ca2+同时作用下激活后成为质膜结合\n蛋白。\n－PKC与PKA一样，将靶蛋白的丝氨酸、苏氨\n酸残基磷酸化。", "page": 13, "level": "掌握", "img": "assets/img/ch11/p013.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "4.1.3 G蛋白偶联受体", "title": "DAG", "notes": "The activation of PKC\ndepends on an increase of\nboth Ca2+ and DAG.\n【中文讲解·对照课本/考点】\n考点：4.1.3 G蛋白偶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 磷脂酰肌醇信号通路 “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→", "page": 14, "level": "掌握", "img": "assets/img/ch11/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "4.1.3 G蛋白偶联受体", "title": "分子开关 (Molecular Switches）", "notes": "在细胞内信号级联放大过程中分子开关信号蛋\n白起关键作用。作为分子开关的蛋白几乎均属\n于以下这两大类：\n1. 分子开关蛋白的活性由磷酸化与去磷酸化\n（磷酸基团的加上和去除）来开启和关闭；\n2. GTP结合蛋白，根据开关蛋白结合GTP或\nGDP来决定这些开关是激活态or失活态。", "page": 15, "level": "掌握", "img": "assets/img/ch11/p015.jpg", "anim": null, "fig": null, "points": ["相对更普遍存在"], "check": {"q": "关于「分子开关 (Molecular Switche…」，下列说法正确的是（　）", "o": ["A. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "B. 活化的Ras-GTP通过其它信号分子使下游的许多蛋", "C. 相对更普遍存在", "D. the first isolated and sequenced proto-oncogene"], "a": "C", "e": "本页要点：相对更普遍存在"}, "cards": null}, {"i": 15, "sec": "4.1.3 G蛋白偶联受体", "title": "蛋白激酶", "notes": "蛋白磷酸水解酶\nGEF         GAP/RGS\nGEF、GDI        “ON”\nGAP/RGS 促进GTP水解“OFF”\n【结合课本/笔记】第二节 细胞通讯与信号传递●细胞通讯与细胞识别●细胞的信号分子与受体●通过细胞内受体介导的信号传递●通过细胞表面受体介导的信号跨膜传递●由细胞表面整合蛋白介导的信号传递●细胞信号传递的基本特征与蛋白激酶的网络整合信息", "page": 16, "level": "掌握", "img": "assets/img/ch11/p016.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 16, "sec": "4.1.3 G蛋白偶联受体", "title": "➢ 蛋白激酶(kinase)", "notes": "An enzyme that transfers the terminal phosphate group from\nATP to a substrate. Protein kinase, which phosphorylate specific\nserine, threonine, or tyrosine residues in target proteins, play a\ncritical role in regulating the activity of many cellular proteins.\n➢ 蛋白磷酸酶/蛋白磷酸水解酶(phosphatase)\nAn enzyme that removes a phosphate group form a substrate\nby hydrolysis.\n（区别于糖原磷酸化酶：glycogen phosphorylase, GP）\n➢ 蛋白酶体(proteasome)\nLarge multifunctional protease complex in the cytosol that\ndegrades intracellular proteins marked for destruction by\nattachment of multiple ubiquitin molecules.\n【中文讲解·对照课本/考点】\n考点：4.1.3 G蛋白偶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 17, "level": "掌握", "img": "assets/img/ch11/p017.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch11_mcq_1", "mod": "4.1.3 G蛋白偶联受体", "modI": 1, "q": "细胞内信号蛋白的相互作用是靠（            ）所特异性介导的。", "o": ["A．蛋白质模式结合域", "B．受体蛋白", "C．G 蛋白偶联受体", "D．疏水性分子相互作用 【答案】A  【解析】靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。"], "a": "A", "e": "靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。", "kp": "ch11_s1_14"}, {"id": "ch11_mcq_4", "mod": "4.1.3 G蛋白偶联受体", "modI": 1, "q": "与细胞内钙离子浓度调控直接相关的信号为（                ）。", "o": ["A．DAG", "B．PKC", "C．CaM", "D．IP3 【答案】D  【解析】IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。"], "a": "D", "e": "IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。", "kp": "ch11_s1_15"}], "judge": [{"id": "ch11_judge_1", "modI": 1, "q": "与胞内受体结合的信号分子多为亲脂性分子。（         ）", "a": "对", "e": "亲脂性分子疏水性较强，可穿过细胞膜进入细胞。", "kp": "ch11_s1_15"}, {"id": "ch11_judge_3", "modI": 1, "q": "受体都分布于质膜表面，在信息传递和细胞识别过程中起信号接收器的作用。(       )", "a": "错", "e": "受体分为胞内受体和胞外受体两种类型。", "kp": "ch11_s1_15"}, {"id": "ch11_judge_7", "modI": 1, "q": "胞内受体一般处于受抑制状态，细胞内信号的作用是解除抑制。（       ）", "a": "对", "e": "", "kp": "ch11_s1_15"}, {"id": "ch11_judge_8", "modI": 1, "q": "IP3 是直接由 PIP2 产生的，PIP2 是从肌醇磷脂衍生而来的，肌醇磷脂没有掺入另外的磷酸 基团。", "a": "对", "e": "PIP2 含有三个磷酸基团，其中一个连接糖与二酰甘油酯。IP3 通过一个简单的水解 反应产生。", "kp": "ch11_s1_11"}], "fill": [{"id": "ch11_fill_1", "modI": 1, "q": "一般将胞外的信号分子称为______，将细胞内最早产生的信号分子称为______。", "a": "第一信使；第二信使", "kp": "ch11_s1_15"}, {"id": "ch11_fill_12", "modI": 1, "q": "细胞识别作用引起三种反应：①是______；②是______；③是______。", "a": "内吞作用；细胞黏着；接触抑制", "kp": "ch11_s1_15"}, {"id": "ch11_fill_13", "modI": 1, "q": "胞内受体一般有三个结构域：①______；②______；③______。", "a": "与信号分子结合的 C 端结构域；与 DNA 结合的中间结构域；活化基因转录的 N 端结构域", "kp": "ch11_s1_15"}, {"id": "ch11_fill_17", "modI": 1, "q": "细胞表面受体丝氨酸∕苏氨酸激酶是_____次跨膜蛋白受体，受体胞内区具有_____活性， 它的主要配体是_____。", "a": "1；丝氨酸∕苏氨酸蛋白激酶；转化生长因子β家族成员", "kp": "ch11_s1_12"}], "short": [{"id": "ch11_short_6", "modI": 1, "q": "Ca2+为何可以作为胞内信号进行信号转导，Ca2+的储存与释放在信号转导中有什么作用？", "a": "在细胞质基质中，基态的 Ca2+浓度约为 l0-7～mol／L，很少的 Ca2+流入就可以导致胞内 溶胶 Ca2+较大程度变化。与 Na+相比，胞内 Na+浓度发生显著改变所需要的离子量要大得多。 在信号转导中，Ca2+作用极其重要，不仅可以作为第三信使参与广泛的生理活动，活化各种 Ca2+结合蛋白并引起细胞反应，而且在双信使系统本身的调节方面也非常重要。胞内 Ca2+ 浓度过高会引起细胞中毒，质膜上的钙泵和钠钙交换器将 Ca2+泵出细胞，内质网膜上的钙 泵会将高浓度的 Ca2+泵进内质网钙库。至少已经发现 4 种以上的钙结合蛋白，每个钙结合蛋 白可与 30 个左右的 Ca2+结合，钙结合蛋白的浓度可达 30～100 mg／mL，内质网作为 Ca2+ 的储存库。", "kp": "ch11_s1_9"}, {"id": "ch11_short_7", "modI": 1, "q": "比较 cAMP 信号系统与 IP3-DAG 信号系统在跨膜信号传递作用的异同。", "a": "二者都是 G 蛋白偶联信号转导系统，但是第二信使不同，分别由不同的效应物生成： cAMP 由腺苷酸环化酶(AC)水解细胞中的 ATP 生成，cAMP 再与蛋白激酶 A(PKA)结合，引 发一系列细胞质反应与细胞核中的作用。在另一种信号转导系统中，效应物磷脂酶 Cq(PLC) 将膜上的磷脂酰肌醇 4，5-二磷酸分解为两个信使：二酰甘油(DAG)与 1，4，5-三磷酸肌醇(IP3)， IP3 动员胞内钙库释放 Ca2+，与钙调蛋白结合引起系列反应，而 DAG 在 Ca2+的协同下激活 蛋白激酶 C(PKC)，再引起级联反应。", "kp": "ch11_s1_11"}, {"id": "ch11_short_9", "modI": 1, "q": "请列举三种以上受体酪氨酸蛋白激酶介导的信号转导的级联通路。", "a": "受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要受体家族。 当配体与受体相结合，激活受体的酪氨酸蛋白激酶活性，随即引起一系列磷酸化级联反应， 最终导致细胞生理和基因表达的改变。其介导的信号转导级联通路举例如下： （1）Grb2 信号通路 活化的受体识别含有 SH2 结构的靶蛋白，当 TPK 受体被激活后便借助于自身磷酸化的酪氨 酸残基与细胞内的信号分子接头蛋白 Grb2 的 SH2 结构结合，激活靶蛋白。 （2）Sos 信号通路 TPK 除含有一个隐含的 SH2 结构域外，还具有两个 SH3 结构域。它的功能是识别并结合下 游的另一个信号分子——鸟苷酸释放因子（Sos），识别部位是 Sos 中富含脯氨酸的区段。 在细胞静息状态时，Grb2 通过两个 SH3 结构与 Sos 结合形成复合物，存在于胞浆中，当 TPK 受体被激活，通过 Grb2 的 N 端 SH2 结构将 Grb2-Sos 复合物与受体相连，并将其转移至细 胞膜上募集 Sos，提高 Sos 在质膜上的局部浓度，Sos 具有核苷酸转移酶的活性，可激活下 游靶蛋白 Ras。 （3）RTK-Ras 蛋白信号通路 Ras 蛋白在 RTK 介导的信号通路中是一种关键组分。Ras 蛋白结合 GTP 时为活化态，而结 合 GDP 时为失活态。所以 Ras 蛋白具有分子开关的作用。Ras 蛋白的活化及其细胞应答是 通过配体与 RTK 的结合而诱导的。由 RTK 介导的信号通路具有广泛的功能，包括调节细胞 的增殖、分化、促进细胞存活，以及细胞代谢过程中的调节与校正作用。各种不同的胞外配 体（生长因子）与 RTK 结合，有时会引起细胞内产生多向性的效应，包括早期和晚期的基 因表达。", "kp": "ch11_s1_15"}, {"id": "ch11_short_11", "modI": 1, "q": "真核细胞为何以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使？（注：细胞质中游 ＋        ＋   离 Ca2 的浓度维持在 10-7mol/L，而 Na 的浓度维持在 10-3mol/L） ＋                     ＋", "a": "真核细胞之所以以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使，主要有两方面 ＋       ＋   的原因： （1）以 Ca2 为细胞内的第三信使，只需要少量的 Ca2 进入细胞，即可达到传递信号所需的 ＋                         ＋   浓度阈值，从而诱发各种细胞反应，即使在细胞外 Ca2 缺乏的情况下也容易达到； ＋   （2）若以 Na 作为第三信使，势必需要很多 Na 进入细胞内，一方面会引起细胞外 Na 的 ＋                   ＋                          ＋   缺少，需要大量 Na 进行补充；另一方面也会引起膜电位的紊乱，对细胞造成伤害。 ＋", "kp": "ch11_s1_12"}, {"id": "ch11_short_12", "modI": 1, "q": "如果说细胞信号产生于多细胞生命形式的需要，那如何解释动物与单细胞的出芽酵母之 间在细胞信号上有如此相似的机制？", "a": "动物与单细胞的出芽酵母之间在细胞信号上有相似机制的原因：多细胞有机体的细胞和 细胞之间需要进行信息交流，所以有信号转导机制。单细胞的出芽酵母也要与周围的环境进 行信息交流，当细胞受到刺激后首先被细胞表面特异性受体所识别，胞外信号通过信使进入 胞内转变为胞内信号，这与多细胞生物是相似的。", "kp": "ch11_s1_15"}, {"id": "ch11_short_13", "modI": 1, "q": "G 蛋白在细胞质膜受体介导的信号传导途径中的功能及其调节。", "a": "（1）G 蛋白在细胞质膜受体介导的信号传导途径中的功能 G 蛋白能够将受体接受的信号传递给效应物，产生第二信使，进行信号转导，某些 G 蛋白 还可直接调节某些离子通道的通透性。 （2）G 蛋白在细胞质膜受体介导的信号传导途径中的调节 G 蛋白由α，β，γ三个不同亚基组成。配体和受体结合，诱导 GTP 与 G 蛋白结合的 GDP 进 行交换，GTP 结合的 G 蛋白处于活化状态，激活位于信号传导途径中的下游分子如腺苷酸 环化酶。G 蛋白α亚基具有内源 GTP 酶活性，当 GTP-Gα水解为 GDP-Gα后，则处于失活状 态。 G 蛋白偶联受体介导的信号通路主要有两条：一条是 cAMP 信号通路，另有一条是磷脂酰 肌醇信号通路。前者是配体与受体结合，激活偶联的 G 蛋白，G 蛋白激活腺苷酸环化酶， 产生第二信使 cAMP，引发下游细胞事件。后者也是配体与受体结合激活偶联的 G 蛋白， 活化的 G 蛋白激活质膜上的磷脂酶 C，使 PIP2 水解为 IP3 和 DAG 两个第二信使，IP3 可动员 细胞内 Ca2 释放，DAG 可激活蛋白激酶 C（PKC），分别激发细胞的下游事件，又称“双信 ＋   使系统”。", "kp": "ch11_s1_15"}], "calc": [], "term": [{"id": "ch11_term_3", "modI": 1, "term": "双信使系统（double messenger system）。", "def": "双信使系统（double messenger system）是指磷脂酰肌醇信号通路的胞外信号被膜蛋白 受体接受后，同时产生两个胞内信使，分别启动两个信号传递途径即 IP3-Ca2+和 DG-PKC 途 径，实现细胞对外界信号的应答的一种信号系统。", "kps": "", "kp": "ch11_s1_9"}, {"id": "ch11_term_7", "modI": 1, "term": "分子开关", "def": "分子开关是指通过激活机制或失活机制精确控制细胞内一系列信号传递级联反应的蛋白 质分子，可分为两类：一类分子开关蛋白的活性由磷酸化和去磷酸化控制，蛋白激酶使之磷 酸化而开放，蛋白磷酸酯酶使之去磷酸化而关闭，许多由可逆磷酸化控制的开关蛋白是蛋白 激酶本身；另一类分子开关蛋白是 GTP 结合蛋白，结合 GTP 而活化，结合 GDP 而失活。", "kps": "", "kp": "ch11_s1_14"}, {"id": "ch11_term_8", "modI": 1, "term": "第二信使", "def": "第二信使是指受细胞外信号的作用，在细胞质溶质内形成或向细胞质溶质释放的细胞内 小分子，负责将信号传到细胞内部，如 cAMP、IP3、Ca2 等。第二信使通过其浓度变化（增 ＋   加或减少）应答胞外信号与细胞表面受体的结合，调节细胞内酶和非酶蛋白的活性，从而在 细胞信号转导途径中行使携带和放大信号的功能。", "kps": "", "kp": "ch11_s1_9"}, {"id": "ch11_term_9", "modI": 1, "term": "cell recognition", "def": "cell recognition 的中文名称细胞识别。细胞识别主要是指细胞表面的受体或者配体与相 邻细胞表面的配体或者受体选择性识别、结合并引起一系列下游生理生化反应的过程，对多 细胞生物体的发育具有重要意义。", "kps": "", "kp": "ch11_s1_15"}]}, {"i": 2, "name": "4.2 酶联受体", "slides": [{"i": 17, "sec": "4.2 酶联受体", "title": "4.2 酶联受体", "notes": "(enzyme linked receptor)\n◆酶联受体本身在细胞内侧一端具有酶的活\n性，当其胞外端与配体信号分子结合后，则\n启动细胞膜内侧另一端的酶活性，并将信号\n放大，又称催化受体(catalytic receptor)。\n◆这类受体传导的信号(生长因子)主要与细\n胞生长、分裂繁殖有关。", "page": 18, "level": "掌握", "img": "assets/img/ch11/p018.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 18, "sec": "4.2 酶联受体", "title": "酪氨酸蛋白激酶活性的受体(Receptor", "notes": "Tyrosine Kinases, RTK)信号通路之\n(RTK-Ras蛋白信号通路)\n通过受体自身的酪氨酸蛋白激酶的激活来完成信\n号跨膜转导的。其信号分子多为一些生长因子。\nSignaling ligands of RTKs\n1.Nerve growth factor 神经生长因子 (NGF)\n2.Platelet-derived growth factor 血小板生长因子\n(PDGF)\n3.Epidermal growth factor 表皮生长(EGF)\n4.insulin and insulin-like GF 胰岛素和类胰岛素(IGF-1)\n5.vascular endothelial factor 血管内皮生长因子(VEGF)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 19, "level": "掌握", "img": "assets/img/ch11/p019.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 19, "sec": "4.2 酶联受体", "title": "Some subfamilies of RTKs", "notes": "【结合课本/笔记】A protein kinaseis an enzyme that modifies other proteins by chemically adding phosphategroups to them (phosphorylation). This usually results in a functionalchange of the target protein (substrate) by changing enzyme activity,cellular location, or association with other proteins.第二信使：是在细胞内的多由胞外信号分子转导的产物，同时又可以介导下一步的信号转\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 20, "level": "掌握", "img": "assets/img/ch11/p020.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 20, "sec": "4.2 酶联受体", "title": "The Structure and Activation of a Receptor", "notes": "Tyrosine Kinase\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 21, "level": "掌握", "img": "assets/img/ch11/p021.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 21, "sec": "4.2 酶联受体", "title": "RTK-Ras蛋白信号通路", "notes": "1) RTK没有信号分子结合时，以无活性的单体存在。\nIn the inactive state, the RTK receptors are in the membrane\nas monomers, Ras is combined with GDP and is inactive.\n2) 信号分子与受体结合，2个单体受体分子在膜上聚和成二聚体。\n二聚化受体酪氨酸残基互相磷酸化：自身磷酸化而激活。\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 22, "level": "掌握", "img": "assets/img/ch11/p022.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 22, "sec": "4.2 酶联受体", "title": "RTKs激活Ras 过程", "notes": "3. 接头蛋白Grb2蛋白\n的SH2结构域与酪氨\n酸激酶结合；\nSH3结构域为Ras激\n活蛋白SOS －鸟苷酸\n交换因子(GEF)提供\n结合位点.", "page": 23, "level": "掌握", "img": "assets/img/ch11/p023.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 23, "sec": "4.2 酶联受体", "title": "GRB2蛋白", "notes": "(growth factor receptor-bound protein 2)\n唯一功能作为接头分子(adaptor)将其它蛋白连\n接到一个复合体中。其中一个结构域(SH2)与磷酸化的\nRTK结合，另一个结构域(SH3)与一个叫SOS的蛋白结\n合。\nSH2/SH3结构域特点：\n高度保守，无酶的催化活性\nThe SH2 domain is a compact,\n“plug-in” module(模块)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 24, "level": "掌握", "img": "assets/img/ch11/p024.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 24, "sec": "4.2 酶联受体", "title": "• src 基因首先在鸡肉瘤病毒（Rous sarcoma virus）中发现", "notes": "SH (Src homolog region)\nOrganization of human Src. CL, catalytic loop; AS, activation segment\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 25, "level": "掌握", "img": "assets/img/ch11/p025.jpg", "anim": null, "fig": null, "points": ["Src位于胞质中，属于非受体型TK (tyrosine kinase)", "SH1 激酶活性区", "SH2 选择性结合磷酸化的Tyr残基", "SH3 选择性结合富含Pro的序列"], "check": {"q": "关于「• src 基因首先在鸡肉瘤病毒（Rous sa…」，下列说法正确的是（　）", "o": ["A. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "B. Calmodulin存在于真核生物，水溶性，存在胞质溶", "C. 促进细胞粘合和胞间通讯", "D. 活化的Ras-GTP通过其它信号分子使下游的许多蛋"], "a": "A", "e": "本页要点：Src位于胞质中，属于非受体型TK (tyrosine kinase)"}, "cards": null}, {"i": 25, "sec": "4.2 酶联受体", "title": "信号分子间的识别结构域⎯SH结构域", "notes": "介导信号分子的相互识别和连接，形成不同的转导途\n径。\ndomain)简称，其中\nSH2结构域选择性紧密结合磷酸化的酪氨酸残基，\n形成多蛋白复合体参与细胞信号转导。\nSH3识别并结合富含Pro(脯氨酸) 的蛋白序列，介\n导蛋白与蛋白间的相互作用。\n注：Src是一种原癌基因，最早在Rous肉瘤病毒\n(Rous sarcoma virus)中发现", "page": 26, "level": "掌握", "img": "assets/img/ch11/p026.jpg", "anim": null, "fig": null, "points": ["SH结构域是Src同源结构域 (Src homology"], "check": {"q": "关于「信号分子间的识别结构域⎯SH结构域」，下列说法正确的是（　）", "o": ["A. RTK signal", "B. SH结构域是Src同源结构域 (Src homology", "C. The resulting conformation", "D. 细胞信号传递的主要特"], "a": "B", "e": "本页要点：SH结构域是Src同源结构域 (Src homology"}, "cards": null}, {"i": 26, "sec": "4.2 酶联受体", "title": "Ras 蛋白：大鼠肉瘤(rat sarcoma, Ras)的英文缩写，是原癌基", "notes": "因Ras的表达产物，分子量21kDa，属单体小G-蛋白，具弱\nGTPase活性，通过结合GTP/GDP相互转换被激活、灭活。\nSOS (son of sevenless):\n是Ras(一种小G蛋白)的激活蛋白－GEF\n即Sos是一种鸟苷酸释放因子，刺激GDP从Ras中释放出来，\n细胞溶质中的GTP进而与之结合，活化Ras。\nSevenless: 果蝇中鉴定出的一种与光受体分化有关的基因", "page": 27, "level": "掌握", "img": "assets/img/ch11/p027.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 27, "sec": "4.2 酶联受体", "title": "Ras 蛋白", "notes": "Ras：rat sarcoma；GTPase 开关蛋白\n分子单体GTP 结合蛋白，具有GTPase 活性，分布于质膜胞质一侧，\n结合GTP 时呈活化态，而结合GDP 时呈失活态\nGDP 的释放需要鸟苷酸交换因子（GEF）参与；\n【结合课本/笔记】核孔复合体的功能核质交换的双向性亲水通道核孔复合体物质运输功能示意图爪蟾卵母细胞核质蛋白注射实验通过核孔复合体的主动运输亲核蛋白与核定位信号亲核蛋白入核转运的步骤转录产物RNA的核输出通过核孔复合体的主动运输生物大分子的核质分配主要是通过核孔复合体的主动运输完成的，具有高度的选择性，并且是双向的。选择性表现在以下三个方面：对运输颗粒大小的限制：有效功能直径可被调节约10～20nm，甚至可达26nm，主动运输是一个信号识别与载体介导的过程，需要消耗能量，并表现出饱和动力学特征主动运输具有双向性，即核输入与核输出亲核蛋白与核定位信号亲核蛋白（karyophilic protein）在细胞质内合成后，需要或能够进入细胞核", "page": 28, "level": "掌握", "img": "assets/img/ch11/p028.jpg", "anim": null, "fig": null, "points": ["Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小", "Ras 蛋白从失活态到活化态的转变，先要GDP 释放才有GTP 的结合，", "Ras 蛋白从活化态到失活态的转变，则要GTP 酶活化蛋白（GAP）的促进"], "check": {"q": "关于「Ras 蛋白」，下列说法正确的是（　）", "o": ["A. 细胞信号传递的主要特", "B. SH结构域是Src同源结构域 (Src homology", "C. Calmodulin存在于真核生物，水溶性，存在胞质溶", "D. Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小"], "a": "D", "e": "本页要点：Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小"}, "cards": null}, {"i": 28, "sec": "4.2 酶联受体", "title": "4. Grb2-Sos induces the", "notes": "exchange of GTP for GDP\non Ras/GDP→Ras-GTP.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 29, "level": "掌握", "img": "assets/img/ch11/p029.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 29, "sec": "4.2 酶联受体", "title": "Raf 蛋白", "notes": "MAPKKK\nMAPKK\n5. 激活的Ras进入一系列\n与有丝分裂原活化蛋白激\n酶(mitogen-activated\nprotein kinase, MAPK) 的   MAPK\n磷酸化的联级放大反应\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 30, "level": "掌握", "img": "assets/img/ch11/p030.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 30, "sec": "4.2 酶联受体", "title": "Cells seem to require two types of signals to proliferate.", "notes": "In order to multiply successfully, most\nnormal cells require both extracellular\nsignals that drive cell-cycle\nprogression(mitogen) and extracellular\nsignals that drive cell growth (growth\nfactor)\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 31, "level": "掌握", "img": "assets/img/ch11/p031.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 31, "sec": "4.2 酶联受体", "title": "RTK-Ras影响细胞的生长、增殖", "notes": "白磷酸化，其中包括一种重要的有丝分裂原活化的蛋\n白激酶(mitogen-activated protein kinase, MAPK) 。\n(Myc等)，增强特异基因的转录来调节细胞的生长、\n增殖。\nMyc is thought to promote cell-cycle entry by several\nmechanisms, one is to increase the expression of genes\nencoding G1 cyclins (cyclin D)，thereby increasing G1-\nCdk (cyclin D/Cdk4) activity.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 细胞周期蛋白（cyclin）：是一类随细胞周期的变化呈周期性出现或消失的蛋白质，可以时相形地激活 CDK，从而调控细胞周期。", "page": 32, "level": "掌握", "img": "assets/img/ch11/p032.jpg", "anim": null, "fig": null, "points": ["活化的Ras-GTP通过其它信号分子使下游的许多蛋", "活化的MAPK进入细胞核，通过磷酸化转录因子"], "check": {"q": "关于「RTK-Ras影响细胞的生长、增殖」，下列说法正确的是（　）", "o": ["A. Calmodulin存在于真核生物，水溶性，存在胞质溶", "B. 促进细胞粘合和胞间通讯", "C. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "D. 活化的Ras-GTP通过其它信号分子使下游的许多蛋"], "a": "D", "e": "本页要点：活化的Ras-GTP通过其它信号分子使下游的许多蛋"}, "cards": null}, {"i": 32, "sec": "4.2 酶联受体", "title": "（本页为图片/无文字层）", "notes": "【图内文字(OCR)】\nmitogenreceptor\nRas\nMAPkinase\nactivationoftranscriptionregulatoryprotein\nCYTOSOL\nNUCLEUS\nimmediateearly\ngeneexpression\ntranscription\nMyc\nregulatory\nprotein\ndelayed-responsegeneexpression\nactive\nG-Cdk\npositivefeedback\nactive\nactiveRb\nG,/S-Cdk\nprotein\nactiveE2F\nprotein\nG/S-cyclin\nS-phasegene\n(cyclin E)\nactive\nDNA\ntranscription\nS-cyclin\nS-Cdk\nSYNTHESIS\n(cyclin A)\ninactivated\nE2Fprotein\npositive\nfeedback\ninactivatedRb\nprotein\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体\n• 磷脂酰肌醇信号通路 “双信使系统”反应链：胞外信号分子→G-蛋白偶联受体→G-蛋白→", "page": 33, "level": "掌握", "img": "assets/img/ch11/p033.jpg", "anim": null, "fig": null, "points": ["mitogenreceptor", "Ras", "MAPkinase", "CYTOSOL", "NUCLEUS", "immediateearly", "geneexpression", "transcription"], "check": null, "cards": null}, {"i": 33, "sec": "4.2 酶联受体", "title": "(原癌基因)", "notes": "Ras, small GTPase (G-protein)\n12或61位残基发生点突变），抑制Ras本身GTPase\n的活性，不能使Ras-GTP水解转化为Ras-GDP,导致\nRas长期处于活性状态，不停地激活下游信号，引起\n细胞异常增殖。编码Ras蛋白的ras基因为原癌基因。\nThe ras gene is known to be mutated in about\none in five human cancers.\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 原癌基因（proto-oncogene）：正常细胞基因组中存在与病毒癌基因相似的一类基因，\f产物是正常细胞增殖所必不可少的，突变为癌基因则导致细胞生长失控。", "page": 34, "level": "掌握", "img": "assets/img/ch11/p034.jpg", "anim": null, "fig": null, "points": ["the first isolated and sequenced proto-oncogene", "在25％~30％的人肿瘤中，发现异常的Ras蛋白（其"], "check": {"q": "关于「原癌基因)」，下列说法正确的是（　）", "o": ["A. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "B. the first isolated and sequenced proto-oncogene", "C. 活化的Ras-GTP通过其它信号分子使下游的许多蛋", "D. 相对更普遍存在"], "a": "B", "e": "本页要点：the first isolated and sequenced proto-oncogene"}, "cards": null}, {"i": 34, "sec": "4.2 酶联受体", "title": "胰岛素", "notes": "胰岛素受体(RTK，22四聚体)自身磷酸化\n同时，将胰岛素受体底物(insulin receptor\nsubstrate, IRS)磷酸化\n结合或激活含有SH2结构域的蛋白质，其中包\n括Grb2", "page": 35, "level": "掌握", "img": "assets/img/ch11/p035.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 35, "sec": "4.2 酶联受体", "title": "Insulin胰岛素受体也属于酪氨酸激酶受体", "notes": "IRS： insulin receptor substrate, 胰岛素受体底物\n【中文讲解·对照课本/考点】\n考点：4.2 酶联受体 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 受体（receptor）：是指任何能够同激素、神经递质、药物或细胞内的信号分子结合并能引起细胞功能改变的生物大分子，通常是指位于细胞膜表面或细胞内与信号分子结合的蛋白质。", "page": 36, "level": "掌握", "img": "assets/img/ch11/p036.jpg", "anim": null, "fig": null, "points": ["RTK signal"], "check": {"q": "关于「Insulin胰岛素受体也属于酪氨酸激酶受体」，下列说法正确的是（　）", "o": ["A. the first isolated and sequenced proto-oncogene", "B. 相对更普遍存在", "C. The resulting conformation", "D. RTK signal"], "a": "D", "e": "本页要点：RTK signal"}, "cards": null}], "mcq": [{"id": "ch11_mcq_2", "mod": "4.2 酶联受体", "modI": 2, "q": "不属于蛋白酪氨酸激酶类型的受体是（            ）。", "o": ["A．EGF 受体", "B．PDGF 受体", "C．TGFβ受体", "D．IGF-1 受体 【答案】C  【解析】TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。"], "a": "C", "e": "TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。", "kp": "ch11_s2_35"}], "judge": [{"id": "ch11_judge_5", "modI": 2, "q": "酪氨酸磷酸化用来构建结合部位，用于其他蛋白质与受体酪氨酸激酶的结合。（         ）", "a": "对", "e": "", "kp": "ch11_s2_35"}, {"id": "ch11_judge_10", "modI": 2, "q": "Ras 蛋白被 SOS 激活后，可激活其下游的 MEK 激酶，再通过激活的 MEK 激酶将 Raf 激 酶激活，引起级联反应。（                ）", "a": "错", "e": "叙述该信号转导的顺序有误，应为 Ras→Raf→MEK。", "kp": "ch11_s2_29"}], "fill": [{"id": "ch11_fill_8", "modI": 2, "q": "生长因子属于______信号分子，不能穿过靶细胞质膜的______。通过与靶细胞表面的 ______结合再经信号转导机制，在细胞内产生______或激活______或______的活性，引起细 胞的应答反应。", "a": "亲水性；脂双分子层；受体；第二信使；蛋白激酶；蛋白磷酸酶", "kp": "ch11_s2_17"}, {"id": "ch11_fill_10", "modI": 2, "q": "30％的人类恶性肿瘤是因为突变的______蛋白能与______合，但不能将其水解为______， 而使这种突变的蛋白一直处于开启状态。", "a": "Ras；GTP；GDP", "kp": "ch11_s2_33"}, {"id": "ch11_fill_11", "modI": 2, "q": "酪氨酸蛋白激酶联系的受体______，但是它的胞内区域具有______，也就是说它的活性 依赖于______。", "a": "本身不具备酶活性；酪氨酸蛋白激酶的结合位点；非受体酪氨酸蛋白激酶", "kp": "ch11_s2_18"}, {"id": "ch11_fill_14", "modI": 2, "q": "受体修饰是细胞适应的一种方式，机理是：①______；或是②______。", "a": "受体被磷酸化后失去与信号分子结合的能力；受体被磷酸化易与抑制物结合而失去 与信号分子结合的能力", "kp": "ch11_s2_26"}, {"id": "ch11_fill_15", "modI": 2, "q": "cGMP 信号通路是酶联受体的一种，受体本身就是______酶。其细胞外部分有信号分子 结合的位点，细胞内部分有一______酶结构域，活化后可催化 GTP 生成 cGMP。 在这个系统中，cGMP 与______系统中的 cAMP 一样都充当第二信使。另外一个研究得比较 清楚的酶联受体信号系统就是 EGF 信号通路。EGF 受体是一种______，分子质量为 170 kDa， 广泛分布于哺乳动物细胞的上皮细胞、人成纤维细胞、胶质细胞、角质细胞等。EGF 受体 是一条含有 1186 个氨基酸的多肽链，由______个结构域组成：即 EGF 结合结构域、______ 和蛋白激酶活性区域。EGF 信号解除是通过胞吞作用进行的，EGF 被吞入后，      再运送至______。 Ras 蛋白的激活与 EGF 信号有关。Ras 蛋白是原癌基因 c-ras 表达的产物，也是一种______ 蛋白，具有鸟苷结合位点。对细胞的生长、分化、细胞骨架、蛋白质运输和分泌等功能产生 调节和影响。在正常情况下，Ras 蛋白基本上都与______结合在一起，定位在细胞膜内表面 上。当 EGF 与受体结合后，受体细胞质面的酪氨酸蛋白激酶被激活后______作用于 Ras 蛋 白，使 Ras 蛋白立即解离______，而与______结合，处于活化状态并发出刺激细胞生长的信 号。", "a": "鸟苷环化；鸟苷环化；PKA；糖蛋白；三；跨膜区；溶酶体；G；GDP；间接；GDP； GTR", "kp": "ch11_s2_17"}], "short": [{"id": "ch11_short_10", "modI": 2, "q": "概述酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点和功能。", "a": "（1）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点 ①受体酪氨酸蛋白激酶：是由 50 多种跨膜受体组成的超家族，其胞外配体是可溶性或膜结 合的多肽或蛋白类激素，包括胰岛素和多种生长因子。胞外配体与受体胞外区结合后，受体 发生二聚化并催化胞内区酪氨酸残基自身磷酸化，进而活化 RTK。磷酸化的酪氨酸可被一 类含有 SH2 结构域的胞内信号蛋白识别，通过级联反应向细胞内进行信号转导。 ②RTK-Ras 信号通路：配体→活化酪氨酸激酶 RTK→活化的酪氨酸激酶 RTK 结合接头蛋白 adaptor-GRF（鸟苷酸释放因子）→促进 GDP 释放→Ras（GTP 结合蛋白）活化，诱导下游 事件：Raf 丝氨酸／苏氨酸蛋白激酶（又称 MAPKKK）活化（使蛋白上的丝氨酸／苏氨酸 残基磷酸化）→活化的 Raf 结合并磷酸化另一种蛋白激酶 MAPKK，导致 MAPKK 活化 （MAPKK 是一种具双重特异的蛋白激酶，它能磷酸化 MAPK 的苏氨酸和酪氨酸残基使之 激活）→MAPK 活化→进入细胞核→其他激酶或基因调控蛋白（转录因子）的磷酸化修饰。 （2）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的功能 调节细胞的增殖与分化，促进细胞存活，以及细胞代谢过程中的调节与校正作用。", "kp": "ch11_s2_18"}], "calc": [{"id": "ch11_calc_4", "modI": 2, "q": "概述受体酪氨酸激酶介导的信号通路的组成、特点及其主要功能。", "a": "（1）受体酪氨酸激酶介导的信号通路的组成 ①受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要的受体家族， 包括 6 个亚族。 ②胞外配体是可溶性或膜结合的多肽或蛋白类激素，包括胰岛素和多种生长因子。 ③接头蛋白，如生长因子受体结合蛋白 2（GRB2）。 ④信号通路中有关的酶，如 GTP 酶活化蛋白（GAP）、与肌醇磷脂代谢有关的酶、蛋白磷 酸酯酶（SyP）以及 Src 类的非受体酪氨酸蛋白激酶等。 ⑤Ras 蛋白，具有 GTPase 活性，结合 GTP 活化，结合 GDP 失活，是一种分子开关。 ⑥鸟苷酸释放因子（GRF）。 ⑦Raf 又称 MAPKKK，是 Ser/Thr 蛋白激酶。 ⑧MAPKK 蛋白激酶和 MAPK。 （2）受体酪氨酸激酶介导的信号通路的特点 ①激活机制为受体之间的二聚体化→自磷酸化→活化自身； ②没有特定的第二信使，要求信号有特定的结构域； ③有 Ras 分子开关的参与； ④介导下游 MAPK 的激活。 （3）受体酪氨酸激酶介导的信号通路的主要功能 该信号通路是这类受体所介导的重要信号通路，具有广泛的功能，包括调节细胞的增殖与分 化，促进细胞的存活，以及细胞代谢过程中的调节与校正等。", "kp": "ch11_s2_35"}], "term": [{"id": "ch11_term_2", "modI": 2, "term": "受体酪氨酸磷酸酯酶（receptor tyrosin phospatases）。", "def": "受体酪氨酸磷酸酯酶（receptor tyrosin phosphatases）是一次性跨膜蛋白受体，受体胞内 区具有蛋白酪氨酸磷酸酯酶活性，结合配体后，使磷酸化的酪氨酸去磷酸化，可逆转 RTK 的作用，在细胞周期调控中也发挥着重要作用。", "kps": "", "kp": "ch11_s2_20"}, {"id": "ch11_term_4", "modI": 2, "term": "Ras 蛋白（rat sarcoma，Ras）。", "def": "是原癌基因 c-ras 的产物，相对分子质量为 21kDa，属单体 G 蛋白，具有弱的 GTP 酶活 性，Ras 蛋白常与 GDP 结合，定位于细胞质膜内表面，当特异配体与受体酪氨酸激酶或其 他细胞表面受体结合后会将其激活。在信号从细胞表面受体传递到细胞核内的过程中发挥重 要作用。", "kps": "", "kp": "ch11_s2_26"}, {"id": "ch11_term_5", "modI": 2, "term": "enzyme-linked receptor", "def": "enzyme-linked receptor 的中文名称是酶联受体。通常与酶连接的细胞表面受体又称催化 性受体，目前已知的酶联受体都是跨膜蛋白，当胞外信号（配体）与受体结合即激活受体胞 内段的酶活性。主要包括①受体酪氨酸激酶；②受体丝氨酸／苏氨酸激酶；③受体酪氨酸磷 酸酯酶；④受体鸟苷酸环化酶；⑤酪氨酸蛋白激酶联系的受体。", "kps": "", "kp": "ch11_s2_17"}]}, {"i": 3, "name": "五 Ca2+ 重要的", "slides": [{"i": 36, "sec": "4.2 酶联受体", "title": "五 Ca2+ 重要的", "notes": "胞内信号分子\nCa2+的多功能性：\n(静息态细胞胞质溶胶中浓度很低，低于10-7M；ER和植物液\n泡/线粒体Ca2+浓度髙10000倍: 10-3M)\nThe concentration of Ca2+ free in the cytosol usually must be\nkept below 0.1-0.2 M.\n【结合课本/笔记】用秋水仙素处理细胞破坏微管,导致细胞变圆,说明微管对维持细胞的不对称形状是重要的。对于细胞突起部分,如纤毛、鞭毛、轴突的形成和维持, 微管亦起关键作用。细胞内物质的运输真核细胞内部是高度区域化的体系, 细胞中合成的物质、一些细胞器等必须经过细胞内运输过程。这种运输过程与细胞骨架体系中的微管及其Motor protein有关。", "page": 37, "level": "掌握", "img": "assets/img/ch11/p037.jpg", "anim": null, "fig": null, "points": ["促进细胞粘合和胞间通讯", "受精作用、肌肉收缩、细胞运动、神经细胞信号传递等", "高浓度Ca2+ 导致细胞死亡"], "check": {"q": "关于「Ca2+ 重要的」，下列说法正确的是（　）", "o": ["A. 促进细胞粘合和胞间通讯", "B. Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小", "C. Calmodulin存在于真核生物，水溶性，存在胞质溶", "D. Src位于胞质中，属于非受体型TK (tyrosine kinase)"], "a": "A", "e": "本页要点：促进细胞粘合和胞间通讯"}, "cards": null}], "mcq": [{"id": "ch11_amcq_1", "mod": "五 Ca2+ 重要的", "modI": 3, "q": "关于「Ca2+ 重要的」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. 促进细胞粘合和胞间通讯", "C. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "D. SH1 激酶活性区"], "a": "B", "e": "本页要点：促进细胞粘合和胞间通讯", "kp": "ch11_s3_36"}], "judge": [{"id": "ch11_judge_4", "modI": 3, "q": "内分泌是细胞对自身分泌的物质产生反应。(        )", "a": "错", "e": "内分泌是由无导管腺体产生的一种或几种激素，直接分泌到血液中，通过血液循环 运输到靶细胞，促进其生理、生化应答的现象。", "kp": "ch11_s3_36"}, {"id": "ch11_ajudge_2", "modI": 3, "q": "促进细胞粘合和胞间通讯", "a": "对", "e": "本页要点：促进细胞粘合和胞间通讯", "kp": "ch11_s3_36"}], "fill": [], "short": [], "calc": [], "term": []}, {"i": 4, "name": "5.1 细胞质中低Ca2+浓度(10-7M)的控制机制", "slides": [{"i": 37, "sec": "5.1 细胞质中低Ca2+浓度(10-7", "title": "5.1 细胞质中低Ca2+浓度(10-7M)的控制机制", "notes": "通常，细胞膜对其高度不通透；\n质膜、内质网膜上含有Ca2+泵(Ca2+ pump)\n&植物细胞液泡膜\n线粒体膜上也有Ca2+转运蛋白，能将细胞质中的\nCa2+运到线粒体基质中。\n－但相比而言，亲和力较低。辅助、只有胞质内浓度\n很高时才显示运输能力。\n当细胞遇到刺激时，主要是通过打开质膜和内质网\n膜上的Ca2+通道(Ca2+ channel)，使膜外的Ca2+快\n速进入细胞内，使胞质溶胶中的Ca2+浓度迅速升高。", "page": 38, "level": "掌握", "img": "assets/img/ch11/p038.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 38, "sec": "5.1 细胞质中低Ca2+浓度(10-7", "title": "细胞内", "notes": "质膜上\nCa2+ is actively pumped out of\nthe cytosol to the cell exterior.\nThe main ways in which eucaryotic cells maintain a\nvery low concentration of free Ca2+ in the cytosol.\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 39, "level": "掌握", "img": "assets/img/ch11/p039.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 39, "sec": "5.1 细胞质中低Ca2+浓度(10-7", "title": "An overview of Ca2+ regulatory in cells", "notes": "【结合课本/笔记】（五）Signal Transduction           （问答英文）ReceptorsDefinition: Any protein that specifically binds to another molecules tomediate cell-cell signaling, adhesion, endocytosis or other cellularprocess. Mostly commonly denotes a protein located in the plasma membraneor cytoplasm that is activated by binding a specific extrace\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程", "page": 40, "level": "掌握", "img": "assets/img/ch11/p040.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 40, "sec": "5.1 细胞质中低Ca2+浓度(10-7", "title": "Ca2+ wave in a Starfish egg induced by a fertilizing", "notes": "sperm\nThe release of Ca2+ Is seen to spread from the point\n(arrow) of sperm entry throughout the entire Egg.\n【中文讲解·对照课本/考点】\n考点：5.1 细胞质中低Ca2+浓度(10-7M)的控制机制 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 对基因组的作用细胞增殖、分化、凋亡的相互关系及其调控细胞信号转导的研究细胞结构体系的组装", "page": 41, "level": "掌握", "img": "assets/img/ch11/p041.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch11_amcq_1", "mod": "5.1 细胞质中低Ca2+浓度(10-7M)的控制机制", "modI": 4, "q": "关于「细胞质中低Ca2+浓度(10-7M)的控制机制」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. 通常，细胞膜对其高度不通透", "C. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "D. SH1 激酶活性区"], "a": "B", "e": "本页要点：通常，细胞膜对其高度不通透", "kp": "ch11_s4_37"}], "judge": [{"id": "ch11_judge_9", "modI": 4, "q": "Ca2 是细胞内广泛存在的信使，细胞质中游离的 Ca2 浓度比胞外高。（ ＋                                     ＋ ）", "a": "错", "e": "细胞质基质中 Ca2 的浓度是严格受控的。钙泵主要存在于细胞膜和内质网膜上， ＋   它将 Ca2 输出细胞或泵入内质网腔中储存起来，以维持细胞内低浓度的游离 Ca2 （一般细 ＋                                              ＋   胞内游离浓度 Ca2 约 10-7mol/L，细胞外 Ca2 为 10-3mol/L）。 ＋                   ＋", "kp": "ch11_s4_37"}, {"id": "ch11_ajudge_2", "modI": 4, "q": "通常，细胞膜对其高度不通透", "a": "对", "e": "本页要点：通常，细胞膜对其高度不通透", "kp": "ch11_s4_37"}], "fill": [], "short": [{"id": "ch11_short_8", "modI": 4, "q": "肌细胞中的肌球蛋白／肌动蛋白系统的收缩是由胞内 Ca2+浓度的增加来触发的。肌细胞 具有特殊的 Ca2+释放通道-里阿诺碱(ryanodine)受体，因为它对药物中的里阿诺碱敏感。里阿 诺碱受体位于肌质网的膜中，与内质网中的 IP3 门控 Ca2+通道相反，操纵里阿诺碱受体的配 体就是 Ca2+。试讨论里阿诺碱受体通道对肌细胞收缩的重要性。", "a": "Ca2+激活的 Ca2+通道产生一个正反馈回路：Ca2+释放的越多，就有更多的 Ca2+通道开放。 因此，胞质溶胶内的 Ca2+信号爆发式地被传送到整个肌细胞，从而确保所有的肌球蛋白／ 肌动蛋白纤维几乎同时收缩。", "kp": "ch11_s4_37"}], "calc": [], "term": []}, {"i": 5, "name": "5.2 Calcium-binding protein 钙结合蛋白", "slides": [{"i": 41, "sec": "5.2 Calcium-binding ", "title": "5.2 Calcium-binding protein 钙结合蛋白", "notes": "Calmodulin, CaM 钙调素、钙调蛋白\nCa2+行使功能时往往不是直接单独作用，而是通过\n结合一些钙结合蛋白，研究最多的是CaM。60年代末，\n钙调素(CaM)发现。\n胶中。 CaM is found in all eukaryotic cells.\n内Ca2+浓度升高，CaM、Ca2+形成复合物。", "page": 42, "level": "掌握", "img": "assets/img/ch11/p042.jpg", "anim": null, "fig": null, "points": ["Calmodulin存在于真核生物，水溶性，存在胞质溶", "静息态细胞中，Ca2+与CaM亲和力很低；刺激后胞"], "check": {"q": "关于「Calcium-binding protein …」，下列说法正确的是（　）", "o": ["A. SH结构域是Src同源结构域 (Src homology", "B. Calmodulin存在于真核生物，水溶性，存在胞质溶", "C. Ras 蛋白（21KD）是Ras 基因表达产物，是由190 个氨基酸残基组成的小", "D. 促进细胞粘合和胞间通讯"], "a": "B", "e": "本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶"}, "cards": null}, {"i": 42, "sec": "5.2 Calcium-binding ", "title": "⎯CaM is a widely distributed", "notes": "cytosolic protein that contains 4\nCa2+-binding sites.\nCa2+/CaM wraps around exposed\nhelices of various target proteins,\nthereby altering their activity.\n【中文讲解·对照课本/考点】\n考点：5.2 Calcium-binding protein 钙结合蛋白 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 形成； 正确折叠涉及驻留蛋白：具有KDEL or HDEL信号蛋白二硫键异构酶（protein disulfide isomerase，PDI）切断二硫键，帮助新合成的蛋白重新形成二硫键并处于正确折叠的状态 结合蛋白（Binding protein，Bip，chaperone）识别错误折叠的蛋白或未装配好的蛋白亚单位，并促进重新折叠与装配。", "page": 43, "level": "掌握", "img": "assets/img/ch11/p043.jpg", "anim": null, "fig": null, "points": ["The resulting conformation"], "check": {"q": "关于「⎯CaM is a widely distrib…」，下列说法正确的是（　）", "o": ["A. the first isolated and sequenced proto-oncogene", "B. 相对更普遍存在", "C. The resulting conformation", "D. RTK signal"], "a": "C", "e": "本页要点：The resulting conformation"}, "cards": null}, {"i": 43, "sec": "5.2 Calcium-binding ", "title": "钙调蛋白激酶", "notes": "Activation of Ca2+/CaM-dependent kinase (CaM-kinase II)\n【中文讲解·对照课本/考点】\n考点：5.2 Calcium-binding protein 钙结合蛋白 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号识别颗粒的受体（又称停泊蛋白docking protein，DP）等在非细胞系统中蛋白质的翻译过程与SRP、DP和微粒体的关系", "page": 44, "level": "掌握", "img": "assets/img/ch11/p044.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch11_amcq_3", "mod": "5.2 Calcium-binding protein 钙结合蛋白", "modI": 5, "q": "关于「Calcium-binding protein 」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "C. SH1 激酶活性区", "D. Calmodulin存在于真核生物，水溶性，存在胞质溶"], "a": "D", "e": "本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶", "kp": "ch11_s5_41"}], "judge": [{"id": "ch11_ajudge_4", "modI": 5, "q": "Calmodulin存在于真核生物，水溶性，存在胞质溶", "a": "对", "e": "本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶", "kp": "ch11_s5_41"}], "fill": [], "short": [], "calc": [], "term": []}, {"i": 6, "name": "六、 不同信号体系间的相互作用", "slides": [{"i": 44, "sec": "六、 不同信号体系间的相互作用", "title": "六、 不同信号体系间的相互作用", "notes": "Interaction and regulation of signaling pathway\n征\n间的crosstalking\n【中文讲解·对照课本/考点】\n考点：六、 不同信号体系间的相互作用 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号趋异（divergence）：是指同一种信号与受体作用后在细胞内分成几个不同的信号途径进行传播，最典型的是受体酪氨酸激酶的信号转导。", "page": 45, "level": "掌握", "img": "assets/img/ch11/p045.jpg", "anim": null, "fig": null, "points": ["细胞信号传递的主要特", "收敛（convergence）", "发散（divergence）", "信号转导具有作用通路"], "check": {"q": "关于「不同信号体系间的相互作用」，下列说法正确的是（　）", "o": ["A. 细胞信号传递的主要特", "B. 相对更普遍存在", "C. RTK signal", "D. The resulting conformation"], "a": "A", "e": "本页要点：细胞信号传递的主要特"}, "cards": null}, {"i": 45, "sec": "六、 不同信号体系间的相互作用", "title": "cross talking", "notes": "【结合课本/笔记】细胞信号传递的基本特征与蛋白激酶的网络整合信息●细胞信号传递的基本特征：具有收敛（convergence）或发散（divergence）的特点细胞的信号传导既具有专一性又有作用机制的相似性信号的放大作用和信号所启动的作用的终止并存细胞以不同的方式产生对信号的适应(失敏与减量调节)●蛋白激酶的网络整合信息与信号网络系统中的cross talk", "page": 46, "level": "掌握", "img": "assets/img/ch11/p046.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 46, "sec": "六、 不同信号体系间的相互作用", "title": "Simplified representation of major signal", "notes": "transduction pathways in mammals\n【中文讲解·对照课本/考点】\n考点：六、 不同信号体系间的相互作用 ｜ 教材：第九章 · 第四节 酶联受体介导的信号转导（p176–182）\n• 信号转导（signal transduction）：指细胞外因子通过与受体（膜受体或核受体）结合，引起细胞内的一系列生物化学反应以及蛋白间相互作用，直至细胞生理反应所需基因开始表达、各种生物学效应形成的过程", "page": 47, "level": "掌握", "img": "assets/img/ch11/p047.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [], "judge": [{"id": "ch11_judge_6", "modI": 6, "q": "参与信号转导的受体都是膜蛋白。（         ）", "a": "错", "e": "细胞内受体则是胞浆蛋白。", "kp": "ch11_s6_44"}], "fill": [{"id": "ch11_fill_3", "modI": 6, "q": "细胞以三种方式进行通讯：______、______和______。", "a": "分泌化学信号；细胞间接触性依赖；细胞间形成间隙连接", "kp": "ch11_s6_45"}, {"id": "ch11_fill_16", "modI": 6, "q": "介导细胞信号传递的受体分为________、__________、_________、和__________。", "a": "细胞内受体；离子通道偶联的受体；G 蛋白偶联受体；酶连接的受体", "kp": "ch11_s6_44"}], "short": [{"id": "ch11_short_1", "modI": 6, "q": "什么是“交叉对话”（cross talking）现象（举例说明）？对此研究有何意义？", "a": "（1）细胞信号传递最重要的特征之一是构成一个复杂的信号网络系统，不同的信号可 能包含有相同的中间信号分子，因而在不同信号通路之间可能产生“交叉对话”（cross talking）。 通过蛋白激酶的网络整合信息是调控复杂的细胞行为使不同信号通路之间实现 cross talking 的一种重要方式。例如，磷脂酶 C 既是 G 蛋白偶联受体信号途径的效应酶，又是 RTK 信号 途径的效应酶，并可最终激活蛋白激酶 C（PKC）。 （2）对信号传递过程中 cross talking 的研究有助于加深对信号传递过程非线性内涵的认识， 对此研究将对深入了解多基因表达调控机制、发育机制、病理过程及疾病控制产生十分重要 的影响。", "kp": "ch11_s6_44"}, {"id": "ch11_short_2", "modI": 6, "q": "整联蛋白在信号传递过程中发挥什么样的作用？", "a": "（1）整联蛋白是细胞表面的跨膜蛋白，由α、β两个亚基组成二聚体，其胞外段具有多 种胞外基质组分的结合位点，包括纤连蛋白、胶原和蛋白聚糖的结合位点。 （2）整联蛋白不仅介导细胞附着到细胞外基质上，更重要的是提供了一种细胞外环境调控 细胞内活性的渠道。整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞 质基质，肌醇第二信使的合成，胞内酪氨酸残基的磷酸化等。这些信号对细胞具有深远影响， 诸如细胞生长、迁移、分化乃至生存。", "kp": "ch11_s6_45"}, {"id": "ch11_short_5", "modI": 6, "q": "细胞是如何实现对信号的适应的？", "a": "细胞以不同的方式产生对信号的适应：（1）逐渐降低表面受体的数目，游离受体的减 少降低了对外界信号的敏感度；（2）快速钝化受体(受体本身脱敏)，从而降低受体和配体 的亲和力，降低受体对胞外微量配体的敏感性；（3）在受体已被激活的情况下，其下游信 号蛋白发生变化，使通路受阻，这种适应是通过副反馈实现的，即强反应调节使其自身反应 关闭。", "kp": "ch11_s6_45"}], "calc": [{"id": "ch11_calc_1", "modI": 6, "q": "请比较神经细胞与分泌激素的内分泌细胞信号传导的异同。并讨论两种机制的优点。", "a": "（1）相同点：两类细胞产生的信号都能够长距离传导：神经元能够沿着长轴突传递动 作电位，而激素则通过循环系统到达机体各处。 （2）不同点：由于在一个突触处神经元分泌大量的神经递质，因此浓度非常高，从而神经 递质受体只需以低亲和力与神经递质结合。相反，激素在血液中被极大地稀释，它们以很低 的浓度进入循环。因此，激素受体一般以极高的亲和力与相应激素结合。 （3）靶细胞通过感受血液中激素的水平作出应答；而一个神经元通过特定的突触联系与选 定的靶细胞通讯。神经信号传递速度很快，仅受动作电位的传播速度与突触的工作情况所限 制；而激素信号则比较慢，其限制因素是循环速度和远距离的扩散。", "kp": "ch11_s6_45"}, {"id": "ch11_calc_2", "modI": 6, "q": "试分析信号转导(transduction)的几条通路的共性与特性。", "a": "cAMP 信号通路，磷脂酰肌醇信号通路，受体酪氨酸激]醛}-Ras 信号通路是细胞信号转 导研究比较多的信号通路。 他们的共性与特性有：（1）多途径、多层次的细胞信号传递通路具有收敛或发散的特点； （2）细胞的信号转导既具有专一性又有作用机制的相似性；（3）信号转导过程具有信号放 大作用，其放大作用又必须受到适度的控制，表现为信号的放大作用和信号的终止作用并存， 例如，各条信号通路中蛋白质或酶的磷酸化与去磷酸化起信号的传递，级联放大以及终止等 类似作用；（4）细胞对长期的信号刺激反应能进行自身调节。", "kp": "ch11_s6_46"}, {"id": "ch11_calc_5", "modI": 6, "q": "概述细胞信号的整合方式与控制机制。", "a": "（1）细胞信号的整合方式 细胞的信号转导是多通路、多环节、多层次和高度复杂的可控过程。细胞对信号的应答反应 具有收敛或发散的特点，细胞信号的整合方式分为以下 3 种： ①信号的强度和持续的时间不同控制反应的性质。每种受体都能识别和结合各自的特异性配 体，来自各种非相关受体的信号可以在细胞内收敛成激活一个共同的效应器的信号，从而引 起细胞生理、生化反应和细胞行为的改变。另外，来自相同配体的信号又可发散激活各种不 同的效应器，导致多样化的细胞应答。 ②在不同的细胞中，相同受体因不同的胞内信号蛋白可引发不同的下游通路。细胞的信号转 导既具有专一性又有作用机制的相似性。不同的细胞中，因为转录因子组分不同，即使受体 相同而其下游的通路也是不同的。 ③形成蛋白激酶的网络整合信息。细胞各种不同的信号通路提供了信号途径本身的线性特征， 信号转导最重要的特征之一是构成复杂的信号网络系统，具有高度的非线性特点。因此细胞 需要对各种信号进行整合和精确控制，在各信号通路之间进行“交叉对话”并作出适宜的应答。 整合信号会聚其他信号通路的输入从而修正细胞对信号的反应。 （2）细胞信号的控制机制 ①细胞对外界信号适度的反应既涉及信号的有效刺激和启动，也依赖信号的解除与细胞的反 应终止； ②信号放大与信号终止并存； ③当细胞长期暴露在某种形式的刺激下时，细胞对刺激的反应将会降低； ④细胞以不同的方式对信号进行适应： a．受体没收：细胞通过配体依赖性的受体介导的内吞作用暂时减少细胞表面可利用受体的 数目，但在需要时可以重新释放得以利用。 b．受体下调：细胞通过表面自由受体数目减少和配体的清除机制导致细胞对信号敏感性下 调。 c．信号蛋白失活：受体蛋白未发生改变及影响，而体内的信号蛋白自身发生变化使得信号 通路受阻。 d．抑制性蛋白产生：受体结合配体而被激活后，在下游反应中（如对基因表达的调控）产 生抑制性蛋白并形成负反馈环从而降低或阻断信号转导途径。 e．受体失活：抑制蛋白与受体结合而使得配体无法与受体结合，从而丧失信号通路。", "kp": "ch11_s6_45"}], "term": [{"id": "ch11_term_1", "modI": 6, "term": "信号转导（signal transduction）。", "def": "信号转导（signal transduction）是指外界信号（如光、电、化学分子）作用于细胞表面 受体，引起胞内信使的浓度变化，进而导致细胞应答反应的一系列过程。", "kps": "", "kp": "ch11_s6_46"}]}], "mcq": [{"id": "ch11_mcq_1", "mod": "4.1.3 G蛋白偶联受体", "modI": 1, "q": "细胞内信号蛋白的相互作用是靠（            ）所特异性介导的。", "o": ["A．蛋白质模式结合域", "B．受体蛋白", "C．G 蛋白偶联受体", "D．疏水性分子相互作用 【答案】A  【解析】靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。"], "a": "A", "e": "靠信号蛋白具有不同的模式结合域与另一相匹配的基序识别与结合，在细胞内组装 成不同信号转导复合物，构成细胞内信号传递通路的基础。", "kp": "ch11_s1_14"}, {"id": "ch11_mcq_2", "mod": "4.2 酶联受体", "modI": 2, "q": "不属于蛋白酪氨酸激酶类型的受体是（            ）。", "o": ["A．EGF 受体", "B．PDGF 受体", "C．TGFβ受体", "D．IGF-1 受体 【答案】C  【解析】TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。"], "a": "C", "e": "TGFβ受体即转化生长因子β受体，为受体丝氨酸／苏氨丝氨激酶。", "kp": "ch11_s2_35"}, {"id": "ch11_mcq_3", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "在 cAMP 信号中，G 蛋白的偶联作用表现为（            ）。", "o": ["A．受体的活化导致 G 蛋白的α、β、γ三个亚单位的偶联", "B．受体的活化通过 G 蛋白与 MAPK 激酶级联反应通路偶联", "C．受体的活化通过 G 蛋白与 PKA(cAMP-dependent protein kinase A)的活化偶联 n 受体的活 化通过 G 蛋白与 AC(adenyl cyclase)的活化偶联", "D．受体的活化通过 G 蛋白与 cAMP 偶联 【答案】D  【解析】在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。"], "a": "D", "e": "在 cAMP 信号通路中，三聚体 G 蛋白由α、β、γ三个亚单位组成，受体的活化导致 与 G 蛋白α亚单位相结合的 GDP 被 GTP 交换，而β、γ二聚体共价结合锚于内膜。在 cAMP 信号通路中，处于活化状态的三聚体 G 蛋白亚单位α—GTP 作用于 AC。活化的 AC 使 ATP 环化，生成 cAMP。", "kp": "ch11_s0_0"}, {"id": "ch11_mcq_4", "mod": "4.1.3 G蛋白偶联受体", "modI": 1, "q": "与细胞内钙离子浓度调控直接相关的信号为（                ）。", "o": ["A．DAG", "B．PKC", "C．CaM", "D．IP3 【答案】D  【解析】IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。"], "a": "D", "e": "IP3 通过细胞质基质扩散，结合并打开内质网膜上 IP3 敏感的钙通道，引起钙离子顺 电化学梯度从钙库释放进入细胞质基质，通过钙调蛋白引起细胞反应。", "kp": "ch11_s1_15"}, {"id": "ch11_mcq_5", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "一氧化氮受体是（            ）。", "o": ["A．G 蛋白偶联受体", "B．鸟苷酸环化酶", "C．腺苷酸环化酶", "D．受体酪氨酸激酶 【答案】B  【解析】NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。"], "a": "B", "e": "NO 是种可溶性气体，可作为局部介质在许多组织中发挥作用，靶细胞内可溶性鸟 苷酸环化酶（G-cyclase，GC）的激活是 NO 发挥作用的主要机制。", "kp": "ch11_s0_0"}, {"id": "ch11_mcq_6", "mod": "4.1.2 G-蛋白偶联受体", "modI": 0, "q": "有关 cAMP 信号通路，下列说法错误的是（              ）。", "o": ["A．被激活的蛋白激酶 A 的催化亚基转位进入细胞核，使基因调控蛋白磷酸化", "B．结合 GTP 的α亚基具有活性，而βγ亚基复合物没有活性", "C．βγ亚基复合物与游离的 Gs 的α亚基结合，可使 Gs 的α亚基失活", "D．这一通路的首要效应酶是腺苷酸环化酶，cAMP 被环腺苷磷酸二酯酶消除 【答案】B  【解析】当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。"], "a": "B", "e": "当细胞没有受到激素刺激，Gs 处于非活化态时，Gs 蛋白为异聚体，α亚基与 GDP 结合，此时腺苷酸环化酶没有活性；当激素配体与 Rs 受体结合，导致受体构象改变，暴露 出与 Gs 结合的位点，膜的流动性使激素-受体复合物与 Gs 结合，Gs 的α亚基构象改变，从 而排斥 GDP，结合 GTP 而活化，使三聚体 Gs 蛋白解离出α亚基和βγ亚基复合物，并暴露出 α亚基与腺苷酸环化酶的结合位点，结合 GTP 的α亚基与腺苷酸环化酶结合，使之活化，并 将 ATP 转化为 cAMP。当 Gi 与 GTP 结合，Gi 的α亚基与βγ亚基解离后，一是通过α亚基与 腺苷酸环化酶结合，直接抑制酶的活性，二是通过βγ亚基复合物与游离的 Gs α亚基结合， 阻断的α亚基对腺苷酸环化酶的活化。", "kp": "ch11_s0_2"}, {"id": "ch11_amcq_1", "mod": "五 Ca2+ 重要的", "modI": 3, "q": "关于「Ca2+ 重要的」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. 促进细胞粘合和胞间通讯", "C. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "D. SH1 激酶活性区"], "a": "B", "e": "本页要点：促进细胞粘合和胞间通讯", "kp": "ch11_s3_36"}, {"id": "ch11_amcq_3", "mod": "5.2 Calcium-binding protein 钙结合蛋白", "modI": 5, "q": "关于「Calcium-binding protein 」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "C. SH1 激酶活性区", "D. Calmodulin存在于真核生物，水溶性，存在胞质溶"], "a": "D", "e": "本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶", "kp": "ch11_s5_41"}, {"id": "ch11_amcq_1", "mod": "5.1 细胞质中低Ca2+浓度(10-7M)的控制机制", "modI": 4, "q": "关于「细胞质中低Ca2+浓度(10-7M)的控制机制」，下列说法正确的是（　）", "o": ["A. 相对更普遍存在", "B. 通常，细胞膜对其高度不通透", "C. Src位于胞质中，属于非受体型TK (tyrosine kinase)", "D. SH1 激酶活性区"], "a": "B", "e": "本页要点：通常，细胞膜对其高度不通透", "kp": "ch11_s4_37"}], "judge": [{"id": "ch11_judge_1", "modI": 1, "q": "与胞内受体结合的信号分子多为亲脂性分子。（         ）", "a": "对", "e": "亲脂性分子疏水性较强，可穿过细胞膜进入细胞。", "kp": "ch11_s1_15"}, {"id": "ch11_judge_2", "modI": 0, "q": "G 蛋白偶联受体中，霍乱毒素使 G 蛋白α亚基不能活化，百日咳毒素使 G 蛋白α亚基持续 活化。（      ）", "a": "错", "e": "霍乱毒素，使α亚基丧失 GTP 酶的活性并处于持续活化状态；百日咳毒素抑制 Gi 的活性。", "kp": "ch11_s0_8"}, {"id": "ch11_judge_3", "modI": 1, "q": "受体都分布于质膜表面，在信息传递和细胞识别过程中起信号接收器的作用。(       )", "a": "错", "e": "受体分为胞内受体和胞外受体两种类型。", "kp": "ch11_s1_15"}, {"id": "ch11_judge_4", "modI": 3, "q": "内分泌是细胞对自身分泌的物质产生反应。(        )", "a": "错", "e": "内分泌是由无导管腺体产生的一种或几种激素，直接分泌到血液中，通过血液循环 运输到靶细胞，促进其生理、生化应答的现象。", "kp": "ch11_s3_36"}, {"id": "ch11_judge_5", "modI": 2, "q": "酪氨酸磷酸化用来构建结合部位，用于其他蛋白质与受体酪氨酸激酶的结合。（         ）", "a": "对", "e": "", "kp": "ch11_s2_35"}, {"id": "ch11_judge_6", "modI": 6, "q": "参与信号转导的受体都是膜蛋白。（         ）", "a": "错", "e": "细胞内受体则是胞浆蛋白。", "kp": "ch11_s6_44"}, {"id": "ch11_judge_7", "modI": 1, "q": "胞内受体一般处于受抑制状态，细胞内信号的作用是解除抑制。（       ）", "a": "对", "e": "", "kp": "ch11_s1_15"}, {"id": "ch11_judge_8", "modI": 1, "q": "IP3 是直接由 PIP2 产生的，PIP2 是从肌醇磷脂衍生而来的，肌醇磷脂没有掺入另外的磷酸 基团。", "a": "对", "e": "PIP2 含有三个磷酸基团，其中一个连接糖与二酰甘油酯。IP3 通过一个简单的水解 反应产生。", "kp": "ch11_s1_11"}, {"id": "ch11_judge_9", "modI": 4, "q": "Ca2 是细胞内广泛存在的信使，细胞质中游离的 Ca2 浓度比胞外高。（ ＋                                     ＋ ）", "a": "错", "e": "细胞质基质中 Ca2 的浓度是严格受控的。钙泵主要存在于细胞膜和内质网膜上， ＋   它将 Ca2 输出细胞或泵入内质网腔中储存起来，以维持细胞内低浓度的游离 Ca2 （一般细 ＋                                              ＋   胞内游离浓度 Ca2 约 10-7mol/L，细胞外 Ca2 为 10-3mol/L）。 ＋                   ＋", "kp": "ch11_s4_37"}, {"id": "ch11_judge_10", "modI": 2, "q": "Ras 蛋白被 SOS 激活后，可激活其下游的 MEK 激酶，再通过激活的 MEK 激酶将 Raf 激 酶激活，引起级联反应。（                ）", "a": "错", "e": "叙述该信号转导的顺序有误，应为 Ras→Raf→MEK。", "kp": "ch11_s2_29"}, {"id": "ch11_ajudge_2", "modI": 3, "q": "促进细胞粘合和胞间通讯", "a": "对", "e": "本页要点：促进细胞粘合和胞间通讯", "kp": "ch11_s3_36"}, {"id": "ch11_ajudge_4", "modI": 5, "q": "Calmodulin存在于真核生物，水溶性，存在胞质溶", "a": "对", "e": "本页要点：Calmodulin存在于真核生物，水溶性，存在胞质溶", "kp": "ch11_s5_41"}, {"id": "ch11_ajudge_2", "modI": 4, "q": "通常，细胞膜对其高度不通透", "a": "对", "e": "本页要点：通常，细胞膜对其高度不通透", "kp": "ch11_s4_37"}], "fill": [{"id": "ch11_fill_1", "modI": 1, "q": "一般将胞外的信号分子称为______，将细胞内最早产生的信号分子称为______。", "a": "第一信使；第二信使", "kp": "ch11_s1_15"}, {"id": "ch11_fill_2", "modI": 0, "q": "cAMP 信号通路的效应酶是______，磷脂酰肌醇信号通路的效应酶是______。", "a": "腺苷酸环化酶；磷脂酶 C", "kp": "ch11_s0_0"}, {"id": "ch11_fill_3", "modI": 6, "q": "细胞以三种方式进行通讯：______、______和______。", "a": "分泌化学信号；细胞间接触性依赖；细胞间形成间隙连接", "kp": "ch11_s6_45"}, {"id": "ch11_fill_4", "modI": 0, "q": "受体的本质是______，构成______。", "a": "激素激活的基因调控蛋白；细胞内受体超家族", "kp": "ch11_s0_0"}, {"id": "ch11_fill_5", "modI": 0, "q": "G 蛋白耦联受体是细胞表面由______条多肽______次跨膜形成的受体，N 端在______，C 端在______。N 端与______结合，C 端与______作用。", "a": "单；7；外；内；信号；G 蛋白", "kp": "ch11_s0_4"}, {"id": "ch11_fill_6", "modI": 0, "q": "第一信使指______。", "a": "细胞外信号分子", "kp": "ch11_s0_0"}, {"id": "ch11_fill_7", "modI": 0, "q": "硝酸甘油能用于治疗心绞痛是因为______。", "a": "硝酸甘油在体内转化为 NO，可舒张血管", "kp": "ch11_s0_0"}, {"id": "ch11_fill_8", "modI": 2, "q": "生长因子属于______信号分子，不能穿过靶细胞质膜的______。通过与靶细胞表面的 ______结合再经信号转导机制，在细胞内产生______或激活______或______的活性，引起细 胞的应答反应。", "a": "亲水性；脂双分子层；受体；第二信使；蛋白激酶；蛋白磷酸酶", "kp": "ch11_s2_17"}, {"id": "ch11_fill_9", "modI": 0, "q": "无活性的蛋白激酶 A 有______和______亚基，cAMP 结合它的______使其激活。", "a": "调节亚基；无活性的催化；调节亚基", "kp": "ch11_s0_2"}, {"id": "ch11_fill_10", "modI": 2, "q": "30％的人类恶性肿瘤是因为突变的______蛋白能与______合，但不能将其水解为______， 而使这种突变的蛋白一直处于开启状态。", "a": "Ras；GTP；GDP", "kp": "ch11_s2_33"}, {"id": "ch11_fill_11", "modI": 2, "q": "酪氨酸蛋白激酶联系的受体______，但是它的胞内区域具有______，也就是说它的活性 依赖于______。", "a": "本身不具备酶活性；酪氨酸蛋白激酶的结合位点；非受体酪氨酸蛋白激酶", "kp": "ch11_s2_18"}, {"id": "ch11_fill_12", "modI": 1, "q": "细胞识别作用引起三种反应：①是______；②是______；③是______。", "a": "内吞作用；细胞黏着；接触抑制", "kp": "ch11_s1_15"}, {"id": "ch11_fill_13", "modI": 1, "q": "胞内受体一般有三个结构域：①______；②______；③______。", "a": "与信号分子结合的 C 端结构域；与 DNA 结合的中间结构域；活化基因转录的 N 端结构域", "kp": "ch11_s1_15"}, {"id": "ch11_fill_14", "modI": 2, "q": "受体修饰是细胞适应的一种方式，机理是：①______；或是②______。", "a": "受体被磷酸化后失去与信号分子结合的能力；受体被磷酸化易与抑制物结合而失去 与信号分子结合的能力", "kp": "ch11_s2_26"}, {"id": "ch11_fill_15", "modI": 2, "q": "cGMP 信号通路是酶联受体的一种，受体本身就是______酶。其细胞外部分有信号分子 结合的位点，细胞内部分有一______酶结构域，活化后可催化 GTP 生成 cGMP。 在这个系统中，cGMP 与______系统中的 cAMP 一样都充当第二信使。另外一个研究得比较 清楚的酶联受体信号系统就是 EGF 信号通路。EGF 受体是一种______，分子质量为 170 kDa， 广泛分布于哺乳动物细胞的上皮细胞、人成纤维细胞、胶质细胞、角质细胞等。EGF 受体 是一条含有 1186 个氨基酸的多肽链，由______个结构域组成：即 EGF 结合结构域、______ 和蛋白激酶活性区域。EGF 信号解除是通过胞吞作用进行的，EGF 被吞入后，      再运送至______。 Ras 蛋白的激活与 EGF 信号有关。Ras 蛋白是原癌基因 c-ras 表达的产物，也是一种______ 蛋白，具有鸟苷结合位点。对细胞的生长、分化、细胞骨架、蛋白质运输和分泌等功能产生 调节和影响。在正常情况下，Ras 蛋白基本上都与______结合在一起，定位在细胞膜内表面 上。当 EGF 与受体结合后，受体细胞质面的酪氨酸蛋白激酶被激活后______作用于 Ras 蛋 白，使 Ras 蛋白立即解离______，而与______结合，处于活化状态并发出刺激细胞生长的信 号。", "a": "鸟苷环化；鸟苷环化；PKA；糖蛋白；三；跨膜区；溶酶体；G；GDP；间接；GDP； GTR", "kp": "ch11_s2_17"}, {"id": "ch11_fill_16", "modI": 6, "q": "介导细胞信号传递的受体分为________、__________、_________、和__________。", "a": "细胞内受体；离子通道偶联的受体；G 蛋白偶联受体；酶连接的受体", "kp": "ch11_s6_44"}, {"id": "ch11_fill_17", "modI": 1, "q": "细胞表面受体丝氨酸∕苏氨酸激酶是_____次跨膜蛋白受体，受体胞内区具有_____活性， 它的主要配体是_____。", "a": "1；丝氨酸∕苏氨酸蛋白激酶；转化生长因子β家族成员", "kp": "ch11_s1_12"}], "term": [{"id": "ch11_term_1", "modI": 6, "term": "信号转导（signal transduction）。", "def": "信号转导（signal transduction）是指外界信号（如光、电、化学分子）作用于细胞表面 受体，引起胞内信使的浓度变化，进而导致细胞应答反应的一系列过程。", "kps": "", "kp": "ch11_s6_46"}, {"id": "ch11_term_2", "modI": 2, "term": "受体酪氨酸磷酸酯酶（receptor tyrosin phospatases）。", "def": "受体酪氨酸磷酸酯酶（receptor tyrosin phosphatases）是一次性跨膜蛋白受体，受体胞内 区具有蛋白酪氨酸磷酸酯酶活性，结合配体后，使磷酸化的酪氨酸去磷酸化，可逆转 RTK 的作用，在细胞周期调控中也发挥着重要作用。", "kps": "", "kp": "ch11_s2_20"}, {"id": "ch11_term_3", "modI": 1, "term": "双信使系统（double messenger system）。", "def": "双信使系统（double messenger system）是指磷脂酰肌醇信号通路的胞外信号被膜蛋白 受体接受后，同时产生两个胞内信使，分别启动两个信号传递途径即 IP3-Ca2+和 DG-PKC 途 径，实现细胞对外界信号的应答的一种信号系统。", "kps": "", "kp": "ch11_s1_9"}, {"id": "ch11_term_4", "modI": 2, "term": "Ras 蛋白（rat sarcoma，Ras）。", "def": "是原癌基因 c-ras 的产物，相对分子质量为 21kDa，属单体 G 蛋白，具有弱的 GTP 酶活 性，Ras 蛋白常与 GDP 结合，定位于细胞质膜内表面，当特异配体与受体酪氨酸激酶或其 他细胞表面受体结合后会将其激活。在信号从细胞表面受体传递到细胞核内的过程中发挥重 要作用。", "kps": "", "kp": "ch11_s2_26"}, {"id": "ch11_term_5", "modI": 2, "term": "enzyme-linked receptor", "def": "enzyme-linked receptor 的中文名称是酶联受体。通常与酶连接的细胞表面受体又称催化 性受体，目前已知的酶联受体都是跨膜蛋白，当胞外信号（配体）与受体结合即激活受体胞 内段的酶活性。主要包括①受体酪氨酸激酶；②受体丝氨酸／苏氨酸激酶；③受体酪氨酸磷 酸酯酶；④受体鸟苷酸环化酶；⑤酪氨酸蛋白激酶联系的受体。", "kps": "", "kp": "ch11_s2_17"}, {"id": "ch11_term_6", "modI": 0, "term": "蛋白激酶 VS 蛋白酶体", "def": "蛋白激酶又称蛋白质磷酸化酶，是一类催化蛋白质磷酸化反应的酶，能够特异性地在某 些蛋白质的某些氨基酸位点上添加磷酸基团。蛋白激酶在细胞内的分布遍及核、线粒体、微 粒体和胞液。一般分为 3 大类：①底物专一的蛋白激酶：如磷酸化酶激酶，丙酮酸脱氢酶激 酶等。②依赖于环核苷酸的蛋白激酶：如环腺苷酸（cAMP）蛋白激酶，环鸟苷酸（cGMP） 蛋白激酶。③其他蛋白激酶：如组蛋白激酶等。 蛋白酶体是一类能降解细胞不需要的或受到损伤蛋白质的蛋白复合物。经过蛋白酶体的作用， 蛋白质被切断为约 7～8 个氨基酸长的肽段，这些肽段可以被进一步降解为单个氨基酸分子， 然后被用于合成新的蛋白质。蛋白酶体是细胞用来调控特定蛋白质和除去错误折叠蛋白质的 主要机制。一般来说，需要被降解的蛋白质会先被一个称为泛素的小型蛋白质所标记，被标 记上的蛋白质就会被蛋白酶体降解，因此人们常把蛋白酶体和泛素结合起来，将这一过程称 为泛素依赖性蛋白酶体降解途径。", "kps": "", "kp": "ch11_s0_6"}, {"id": "ch11_term_7", "modI": 1, "term": "分子开关", "def": "分子开关是指通过激活机制或失活机制精确控制细胞内一系列信号传递级联反应的蛋白 质分子，可分为两类：一类分子开关蛋白的活性由磷酸化和去磷酸化控制，蛋白激酶使之磷 酸化而开放，蛋白磷酸酯酶使之去磷酸化而关闭，许多由可逆磷酸化控制的开关蛋白是蛋白 激酶本身；另一类分子开关蛋白是 GTP 结合蛋白，结合 GTP 而活化，结合 GDP 而失活。", "kps": "", "kp": "ch11_s1_14"}, {"id": "ch11_term_8", "modI": 1, "term": "第二信使", "def": "第二信使是指受细胞外信号的作用，在细胞质溶质内形成或向细胞质溶质释放的细胞内 小分子，负责将信号传到细胞内部，如 cAMP、IP3、Ca2 等。第二信使通过其浓度变化（增 ＋   加或减少）应答胞外信号与细胞表面受体的结合，调节细胞内酶和非酶蛋白的活性，从而在 细胞信号转导途径中行使携带和放大信号的功能。", "kps": "", "kp": "ch11_s1_9"}, {"id": "ch11_term_9", "modI": 1, "term": "cell recognition", "def": "cell recognition 的中文名称细胞识别。细胞识别主要是指细胞表面的受体或者配体与相 邻细胞表面的配体或者受体选择性识别、结合并引起一系列下游生理生化反应的过程，对多 细胞生物体的发育具有重要意义。", "kps": "", "kp": "ch11_s1_15"}], "short": [{"id": "ch11_short_1", "modI": 6, "q": "什么是“交叉对话”（cross talking）现象（举例说明）？对此研究有何意义？", "a": "（1）细胞信号传递最重要的特征之一是构成一个复杂的信号网络系统，不同的信号可 能包含有相同的中间信号分子，因而在不同信号通路之间可能产生“交叉对话”（cross talking）。 通过蛋白激酶的网络整合信息是调控复杂的细胞行为使不同信号通路之间实现 cross talking 的一种重要方式。例如，磷脂酶 C 既是 G 蛋白偶联受体信号途径的效应酶，又是 RTK 信号 途径的效应酶，并可最终激活蛋白激酶 C（PKC）。 （2）对信号传递过程中 cross talking 的研究有助于加深对信号传递过程非线性内涵的认识， 对此研究将对深入了解多基因表达调控机制、发育机制、病理过程及疾病控制产生十分重要 的影响。", "kp": "ch11_s6_44"}, {"id": "ch11_short_2", "modI": 6, "q": "整联蛋白在信号传递过程中发挥什么样的作用？", "a": "（1）整联蛋白是细胞表面的跨膜蛋白，由α、β两个亚基组成二聚体，其胞外段具有多 种胞外基质组分的结合位点，包括纤连蛋白、胶原和蛋白聚糖的结合位点。 （2）整联蛋白不仅介导细胞附着到细胞外基质上，更重要的是提供了一种细胞外环境调控 细胞内活性的渠道。整联蛋白与胞外配体的相互作用可产生多种信号，如 Ca2+释放进入细胞 质基质，肌醇第二信使的合成，胞内酪氨酸残基的磷酸化等。这些信号对细胞具有深远影响， 诸如细胞生长、迁移、分化乃至生存。", "kp": "ch11_s6_45"}, {"id": "ch11_short_3", "modI": 0, "q": "G 蛋白偶联受体与酶联受体有什么主要不同点？", "a": "蛋白偶联受体都含有 7 次跨膜的结构域，在信号转导中全部与 G 蛋白偶联；酶联受体 都属于单次跨膜受体，当该类受体与配体结合时导致受体二聚化形成同源或异源多聚化。", "kp": "ch11_s0_8"}, {"id": "ch11_short_4", "modI": 0, "q": "简述 cAMP 途径中的 Gs 调节模型。", "a": "在该途径中由刺激型 Gs 蛋白复合物偶联刺激型受体与腺苷酸环化酶。当细胞没有接受 刺激信号时，Gs 处于非活化状态，Gs 蛋白为异三聚体，α亚基与 GDP 结合，这时腺苷酸环 化酶没有活性。当刺激型的第一信使作用于刺激型的受体后，导致受体构象改变，受体复合 物与 GS 结合引起 Gs 的α亚基构象变化排斥 GDP，而与 GTP 结合被活化，三聚体 Gs 解离 出α亚基和贝塔嘎嘛亚基复合物，活化的刺激型 Gsα亚基继激活腺苷酸环化酶的活性，从而 产生第二信使 cAMP，由于 cAMP 的浓度升高，引起细胞内依赖于 cAMP 的靶酶活化，由 此将胞外信号转换成胞内信号传递、放大以致调节细胞生理反应或基因的表达等。随着 GTP 的水解使α亚基恢复原来的构象并导致与腺苷酸环化酶解离，终止腺苷酸环化酶的活化作 用,α亚基和βγ亚基重新结合，使细胞回复到静止状态。", "kp": "ch11_s0_8"}, {"id": "ch11_short_5", "modI": 6, "q": "细胞是如何实现对信号的适应的？", "a": "细胞以不同的方式产生对信号的适应：（1）逐渐降低表面受体的数目，游离受体的减 少降低了对外界信号的敏感度；（2）快速钝化受体(受体本身脱敏)，从而降低受体和配体 的亲和力，降低受体对胞外微量配体的敏感性；（3）在受体已被激活的情况下，其下游信 号蛋白发生变化，使通路受阻，这种适应是通过副反馈实现的，即强反应调节使其自身反应 关闭。", "kp": "ch11_s6_45"}, {"id": "ch11_short_6", "modI": 1, "q": "Ca2+为何可以作为胞内信号进行信号转导，Ca2+的储存与释放在信号转导中有什么作用？", "a": "在细胞质基质中，基态的 Ca2+浓度约为 l0-7～mol／L，很少的 Ca2+流入就可以导致胞内 溶胶 Ca2+较大程度变化。与 Na+相比，胞内 Na+浓度发生显著改变所需要的离子量要大得多。 在信号转导中，Ca2+作用极其重要，不仅可以作为第三信使参与广泛的生理活动，活化各种 Ca2+结合蛋白并引起细胞反应，而且在双信使系统本身的调节方面也非常重要。胞内 Ca2+ 浓度过高会引起细胞中毒，质膜上的钙泵和钠钙交换器将 Ca2+泵出细胞，内质网膜上的钙 泵会将高浓度的 Ca2+泵进内质网钙库。至少已经发现 4 种以上的钙结合蛋白，每个钙结合蛋 白可与 30 个左右的 Ca2+结合，钙结合蛋白的浓度可达 30～100 mg／mL，内质网作为 Ca2+ 的储存库。", "kp": "ch11_s1_9"}, {"id": "ch11_short_7", "modI": 1, "q": "比较 cAMP 信号系统与 IP3-DAG 信号系统在跨膜信号传递作用的异同。", "a": "二者都是 G 蛋白偶联信号转导系统，但是第二信使不同，分别由不同的效应物生成： cAMP 由腺苷酸环化酶(AC)水解细胞中的 ATP 生成，cAMP 再与蛋白激酶 A(PKA)结合，引 发一系列细胞质反应与细胞核中的作用。在另一种信号转导系统中，效应物磷脂酶 Cq(PLC) 将膜上的磷脂酰肌醇 4，5-二磷酸分解为两个信使：二酰甘油(DAG)与 1，4，5-三磷酸肌醇(IP3)， IP3 动员胞内钙库释放 Ca2+，与钙调蛋白结合引起系列反应，而 DAG 在 Ca2+的协同下激活 蛋白激酶 C(PKC)，再引起级联反应。", "kp": "ch11_s1_11"}, {"id": "ch11_short_8", "modI": 4, "q": "肌细胞中的肌球蛋白／肌动蛋白系统的收缩是由胞内 Ca2+浓度的增加来触发的。肌细胞 具有特殊的 Ca2+释放通道-里阿诺碱(ryanodine)受体，因为它对药物中的里阿诺碱敏感。里阿 诺碱受体位于肌质网的膜中，与内质网中的 IP3 门控 Ca2+通道相反，操纵里阿诺碱受体的配 体就是 Ca2+。试讨论里阿诺碱受体通道对肌细胞收缩的重要性。", "a": "Ca2+激活的 Ca2+通道产生一个正反馈回路：Ca2+释放的越多，就有更多的 Ca2+通道开放。 因此，胞质溶胶内的 Ca2+信号爆发式地被传送到整个肌细胞，从而确保所有的肌球蛋白／ 肌动蛋白纤维几乎同时收缩。", "kp": "ch11_s4_37"}, {"id": "ch11_short_9", "modI": 1, "q": "请列举三种以上受体酪氨酸蛋白激酶介导的信号转导的级联通路。", "a": "受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要受体家族。 当配体与受体相结合，激活受体的酪氨酸蛋白激酶活性，随即引起一系列磷酸化级联反应， 最终导致细胞生理和基因表达的改变。其介导的信号转导级联通路举例如下： （1）Grb2 信号通路 活化的受体识别含有 SH2 结构的靶蛋白，当 TPK 受体被激活后便借助于自身磷酸化的酪氨 酸残基与细胞内的信号分子接头蛋白 Grb2 的 SH2 结构结合，激活靶蛋白。 （2）Sos 信号通路 TPK 除含有一个隐含的 SH2 结构域外，还具有两个 SH3 结构域。它的功能是识别并结合下 游的另一个信号分子——鸟苷酸释放因子（Sos），识别部位是 Sos 中富含脯氨酸的区段。 在细胞静息状态时，Grb2 通过两个 SH3 结构与 Sos 结合形成复合物，存在于胞浆中，当 TPK 受体被激活，通过 Grb2 的 N 端 SH2 结构将 Grb2-Sos 复合物与受体相连，并将其转移至细 胞膜上募集 Sos，提高 Sos 在质膜上的局部浓度，Sos 具有核苷酸转移酶的活性，可激活下 游靶蛋白 Ras。 （3）RTK-Ras 蛋白信号通路 Ras 蛋白在 RTK 介导的信号通路中是一种关键组分。Ras 蛋白结合 GTP 时为活化态，而结 合 GDP 时为失活态。所以 Ras 蛋白具有分子开关的作用。Ras 蛋白的活化及其细胞应答是 通过配体与 RTK 的结合而诱导的。由 RTK 介导的信号通路具有广泛的功能，包括调节细胞 的增殖、分化、促进细胞存活，以及细胞代谢过程中的调节与校正作用。各种不同的胞外配 体（生长因子）与 RTK 结合，有时会引起细胞内产生多向性的效应，包括早期和晚期的基 因表达。", "kp": "ch11_s1_15"}, {"id": "ch11_short_10", "modI": 2, "q": "概述酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点和功能。", "a": "（1）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的特点 ①受体酪氨酸蛋白激酶：是由 50 多种跨膜受体组成的超家族，其胞外配体是可溶性或膜结 合的多肽或蛋白类激素，包括胰岛素和多种生长因子。胞外配体与受体胞外区结合后，受体 发生二聚化并催化胞内区酪氨酸残基自身磷酸化，进而活化 RTK。磷酸化的酪氨酸可被一 类含有 SH2 结构域的胞内信号蛋白识别，通过级联反应向细胞内进行信号转导。 ②RTK-Ras 信号通路：配体→活化酪氨酸激酶 RTK→活化的酪氨酸激酶 RTK 结合接头蛋白 adaptor-GRF（鸟苷酸释放因子）→促进 GDP 释放→Ras（GTP 结合蛋白）活化，诱导下游 事件：Raf 丝氨酸／苏氨酸蛋白激酶（又称 MAPKKK）活化（使蛋白上的丝氨酸／苏氨酸 残基磷酸化）→活化的 Raf 结合并磷酸化另一种蛋白激酶 MAPKK，导致 MAPKK 活化 （MAPKK 是一种具双重特异的蛋白激酶，它能磷酸化 MAPK 的苏氨酸和酪氨酸残基使之 激活）→MAPK 活化→进入细胞核→其他激酶或基因调控蛋白（转录因子）的磷酸化修饰。 （2）酪氨酸蛋白激酶受体介导的 RTK-Ras 信号通路的功能 调节细胞的增殖与分化，促进细胞存活，以及细胞代谢过程中的调节与校正作用。", "kp": "ch11_s2_18"}, {"id": "ch11_short_11", "modI": 1, "q": "真核细胞为何以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使？（注：细胞质中游 ＋        ＋   离 Ca2 的浓度维持在 10-7mol/L，而 Na 的浓度维持在 10-3mol/L） ＋                     ＋", "a": "真核细胞之所以以游离状态 Ca2 ，而不是以 Na 为细胞内的第三信使，主要有两方面 ＋       ＋   的原因： （1）以 Ca2 为细胞内的第三信使，只需要少量的 Ca2 进入细胞，即可达到传递信号所需的 ＋                         ＋   浓度阈值，从而诱发各种细胞反应，即使在细胞外 Ca2 缺乏的情况下也容易达到； ＋   （2）若以 Na 作为第三信使，势必需要很多 Na 进入细胞内，一方面会引起细胞外 Na 的 ＋                   ＋                          ＋   缺少，需要大量 Na 进行补充；另一方面也会引起膜电位的紊乱，对细胞造成伤害。 ＋", "kp": "ch11_s1_12"}, {"id": "ch11_short_12", "modI": 1, "q": "如果说细胞信号产生于多细胞生命形式的需要，那如何解释动物与单细胞的出芽酵母之 间在细胞信号上有如此相似的机制？", "a": "动物与单细胞的出芽酵母之间在细胞信号上有相似机制的原因：多细胞有机体的细胞和 细胞之间需要进行信息交流，所以有信号转导机制。单细胞的出芽酵母也要与周围的环境进 行信息交流，当细胞受到刺激后首先被细胞表面特异性受体所识别，胞外信号通过信使进入 胞内转变为胞内信号，这与多细胞生物是相似的。", "kp": "ch11_s1_15"}, {"id": "ch11_short_13", "modI": 1, "q": "G 蛋白在细胞质膜受体介导的信号传导途径中的功能及其调节。", "a": "（1）G 蛋白在细胞质膜受体介导的信号传导途径中的功能 G 蛋白能够将受体接受的信号传递给效应物，产生第二信使，进行信号转导，某些 G 蛋白 还可直接调节某些离子通道的通透性。 （2）G 蛋白在细胞质膜受体介导的信号传导途径中的调节 G 蛋白由α，β，γ三个不同亚基组成。配体和受体结合，诱导 GTP 与 G 蛋白结合的 GDP 进 行交换，GTP 结合的 G 蛋白处于活化状态，激活位于信号传导途径中的下游分子如腺苷酸 环化酶。G 蛋白α亚基具有内源 GTP 酶活性，当 GTP-Gα水解为 GDP-Gα后，则处于失活状 态。 G 蛋白偶联受体介导的信号通路主要有两条：一条是 cAMP 信号通路，另有一条是磷脂酰 肌醇信号通路。前者是配体与受体结合，激活偶联的 G 蛋白，G 蛋白激活腺苷酸环化酶， 产生第二信使 cAMP，引发下游细胞事件。后者也是配体与受体结合激活偶联的 G 蛋白， 活化的 G 蛋白激活质膜上的磷脂酶 C，使 PIP2 水解为 IP3 和 DAG 两个第二信使，IP3 可动员 细胞内 Ca2 释放，DAG 可激活蛋白激酶 C（PKC），分别激发细胞的下游事件，又称“双信 ＋   使系统”。", "kp": "ch11_s1_15"}], "calc": [{"id": "ch11_calc_1", "modI": 6, "q": "请比较神经细胞与分泌激素的内分泌细胞信号传导的异同。并讨论两种机制的优点。", "a": "（1）相同点：两类细胞产生的信号都能够长距离传导：神经元能够沿着长轴突传递动 作电位，而激素则通过循环系统到达机体各处。 （2）不同点：由于在一个突触处神经元分泌大量的神经递质，因此浓度非常高，从而神经 递质受体只需以低亲和力与神经递质结合。相反，激素在血液中被极大地稀释，它们以很低 的浓度进入循环。因此，激素受体一般以极高的亲和力与相应激素结合。 （3）靶细胞通过感受血液中激素的水平作出应答；而一个神经元通过特定的突触联系与选 定的靶细胞通讯。神经信号传递速度很快，仅受动作电位的传播速度与突触的工作情况所限 制；而激素信号则比较慢，其限制因素是循环速度和远距离的扩散。", "kp": "ch11_s6_45"}, {"id": "ch11_calc_2", "modI": 6, "q": "试分析信号转导(transduction)的几条通路的共性与特性。", "a": "cAMP 信号通路，磷脂酰肌醇信号通路，受体酪氨酸激]醛}-Ras 信号通路是细胞信号转 导研究比较多的信号通路。 他们的共性与特性有：（1）多途径、多层次的细胞信号传递通路具有收敛或发散的特点； （2）细胞的信号转导既具有专一性又有作用机制的相似性；（3）信号转导过程具有信号放 大作用，其放大作用又必须受到适度的控制，表现为信号的放大作用和信号的终止作用并存， 例如，各条信号通路中蛋白质或酶的磷酸化与去磷酸化起信号的传递，级联放大以及终止等 类似作用；（4）细胞对长期的信号刺激反应能进行自身调节。", "kp": "ch11_s6_46"}, {"id": "ch11_calc_3", "modI": 0, "q": "如何理解信号系统及其功能?", "a": "（1）信号系统的基本组成及信号蛋白 ①通过细胞表面受体介导的信号途径的步骤组成： a．细胞通过特异性受体识别胞外信号分子； b．信号跨膜转导； c．通过胞内级联反应实现信号放大作用，并终止细胞活性改变； d．由于信号分子失活，细胞反应终止或下调。 ②相关信号蛋白： a．细胞表面受体；b．转承蛋白；c．信使蛋白；d．接头蛋白；e．放大和转导蛋白；f．传 感蛋白；g．分歧蛋白；h．整合蛋白；i．潜在基因调控蛋白。 （2）信号转导系统的功能 ①相关信号蛋白的功能如下： a．细胞表面受体：特异识别胞外信号。 b．转承蛋白：负责信息向下传递。 c．信使蛋白：携带信号从一部分传递到另外一部分。 d．接头蛋白：连接信号蛋白。 e．放大和转导蛋白：由酶和离子通道组成，介导信号级联反应。 f．传感蛋白：负责不同形式信号的转换。 g．分歧蛋白：信号从一条途径传递到另外一条途径。 h．整合蛋白：从多条通路接受信号并向下传递。 i．潜在基因调控蛋白：在表面被受体活化，迁移到细胞核刺激基因转录。 ②细胞内信号蛋白的相互作用是靠蛋白质模式结合域特异性介导的。信号蛋白具有不同的模 式结合域与另一相匹配的基序识别并结合，在细胞内组装成不同的信号转导复合物，构成细 胞内信号传递通路的基础。 ③信号转导系统的主要作用：特异性、放大作用、信号终止、整合作用。", "kp": "ch11_s0_0"}, {"id": "ch11_calc_4", "modI": 2, "q": "概述受体酪氨酸激酶介导的信号通路的组成、特点及其主要功能。", "a": "（1）受体酪氨酸激酶介导的信号通路的组成 ①受体酪氨酸激酶（RTK）又称酪氨酸蛋白激酶受体，是细胞表面一大类重要的受体家族， 包括 6 个亚族。 ②胞外配体是可溶性或膜结合的多肽或蛋白类激素，包括胰岛素和多种生长因子。 ③接头蛋白，如生长因子受体结合蛋白 2（GRB2）。 ④信号通路中有关的酶，如 GTP 酶活化蛋白（GAP）、与肌醇磷脂代谢有关的酶、蛋白磷 酸酯酶（SyP）以及 Src 类的非受体酪氨酸蛋白激酶等。 ⑤Ras 蛋白，具有 GTPase 活性，结合 GTP 活化，结合 GDP 失活，是一种分子开关。 ⑥鸟苷酸释放因子（GRF）。 ⑦Raf 又称 MAPKKK，是 Ser/Thr 蛋白激酶。 ⑧MAPKK 蛋白激酶和 MAPK。 （2）受体酪氨酸激酶介导的信号通路的特点 ①激活机制为受体之间的二聚体化→自磷酸化→活化自身； ②没有特定的第二信使，要求信号有特定的结构域； ③有 Ras 分子开关的参与； ④介导下游 MAPK 的激活。 （3）受体酪氨酸激酶介导的信号通路的主要功能 该信号通路是这类受体所介导的重要信号通路，具有广泛的功能，包括调节细胞的增殖与分 化，促进细胞的存活，以及细胞代谢过程中的调节与校正等。", "kp": "ch11_s2_35"}, {"id": "ch11_calc_5", "modI": 6, "q": "概述细胞信号的整合方式与控制机制。", "a": "（1）细胞信号的整合方式 细胞的信号转导是多通路、多环节、多层次和高度复杂的可控过程。细胞对信号的应答反应 具有收敛或发散的特点，细胞信号的整合方式分为以下 3 种： ①信号的强度和持续的时间不同控制反应的性质。每种受体都能识别和结合各自的特异性配 体，来自各种非相关受体的信号可以在细胞内收敛成激活一个共同的效应器的信号，从而引 起细胞生理、生化反应和细胞行为的改变。另外，来自相同配体的信号又可发散激活各种不 同的效应器，导致多样化的细胞应答。 ②在不同的细胞中，相同受体因不同的胞内信号蛋白可引发不同的下游通路。细胞的信号转 导既具有专一性又有作用机制的相似性。不同的细胞中，因为转录因子组分不同，即使受体 相同而其下游的通路也是不同的。 ③形成蛋白激酶的网络整合信息。细胞各种不同的信号通路提供了信号途径本身的线性特征， 信号转导最重要的特征之一是构成复杂的信号网络系统，具有高度的非线性特点。因此细胞 需要对各种信号进行整合和精确控制，在各信号通路之间进行“交叉对话”并作出适宜的应答。 整合信号会聚其他信号通路的输入从而修正细胞对信号的反应。 （2）细胞信号的控制机制 ①细胞对外界信号适度的反应既涉及信号的有效刺激和启动，也依赖信号的解除与细胞的反 应终止； ②信号放大与信号终止并存； ③当细胞长期暴露在某种形式的刺激下时，细胞对刺激的反应将会降低； ④细胞以不同的方式对信号进行适应： a．受体没收：细胞通过配体依赖性的受体介导的内吞作用暂时减少细胞表面可利用受体的 数目，但在需要时可以重新释放得以利用。 b．受体下调：细胞通过表面自由受体数目减少和配体的清除机制导致细胞对信号敏感性下 调。 c．信号蛋白失活：受体蛋白未发生改变及影响，而体内的信号蛋白自身发生变化使得信号 通路受阻。 d．抑制性蛋白产生：受体结合配体而被激活后，在下游反应中（如对基因表达的调控）产 生抑制性蛋白并形成负反馈环从而降低或阻断信号转导途径。 e．受体失活：抑制蛋白与受体结合而使得配体无法与受体结合，从而丧失信号通路。", "kp": "ch11_s6_45"}]};